import {b, type ReviewedLesson} from './types';

const lessons: Record<string, ReviewedLesson> = {
  'm2-w081-e1': {
    title: b('One RTS mean and covariance update','Một bước cập nhật mean và covariance RTS'),
    prompt: b(String.raw`Given $m_{t|t}=2$, $m_{t+1|t}=3$, $m_{t+1|T}=1$, $J_t=0.25$, $P_{t|t}=2$, $P_{t+1|t}=4$, and $P_{t+1|T}=1$, compute the smoothed mean and variance.`,String.raw`Cho $m_{t|t}=2$, $m_{t+1|t}=3$, $m_{t+1|T}=1$, $J_t=0.25$, $P_{t|t}=2$, $P_{t+1|t}=4$, $P_{t+1|T}=1$, hãy tính mean và phương sai đã làm trơn.`),
    application: b('A fixed-interval smoother revises the state estimate and uncertainty at time t after later observations alter the estimate at t+1.','Bộ làm trơn khoảng cố định điều chỉnh ước lượng trạng thái và bất định tại t sau khi quan sát sau làm đổi ước lượng tại t+1.'),
    formula: b(String.raw`For a linear Gaussian model with invertible $P_{t+1|t}$, $m_{t|T}=m_{t|t}+J_t(m_{t+1|T}-m_{t+1|t})$ and $P_{t|T}=P_{t|t}+J_t(P_{t+1|T}-P_{t+1|t})J_t^	op$.`,String.raw`Với mô hình Gaussian tuyến tính và $P_{t+1|t}$ khả nghịch, $m_{t|T}=m_{t|t}+J_t(m_{t+1|T}-m_{t+1|t})$ và $P_{t|T}=P_{t|t}+J_t(P_{t+1|T}-P_{t+1|t})J_t^	op$.`),
    steps: [
      b(String.raw`Subtract the next-state prediction from its smoothed estimate: $1-3=-2$.`,String.raw`Lấy ước lượng đã làm trơn trừ dự báo trạng thái kế tiếp: $1-3=-2$.`),
      b(String.raw`Multiply by the gain and add to the filtered mean: $2+0.25(-2)=1.5$.`,String.raw`Nhân với gain rồi cộng vào mean đã lọc: $2+0.25(-2)=1.5$.`),
      b(String.raw`For covariance, use the covariance correction, not the mean correction: $2+0.25^2(1-4)=1.8125$.`,String.raw`Với covariance, dùng hiệu chỉnh covariance chứ không dùng hiệu chỉnh mean: $2+0.25^2(1-4)=1.8125$.`),
    ],
    primarySolution: [
      b(String.raw`The next-state mean innovation is $m_{t+1|T}-m_{t+1|t}=1-3=-2$.`,String.raw`Innovation mean của trạng thái kế tiếp là $m_{t+1|T}-m_{t+1|t}=1-3=-2$.`),
      b(String.raw`Thus $m_{t|T}=2+0.25(-2)=1.5$.`,String.raw`Do đó $m_{t|T}=2+0.25(-2)=1.5$.`),
      b(String.raw`The covariance difference is $1-4=-3$, and the scalar gain is squared: $P_{t|T}=2+0.25^2(-3)=2-0.1875=1.8125$.`,String.raw`Hiệu covariance là $1-4=-3$, còn gain vô hướng phải bình phương: $P_{t|T}=2+0.25^2(-3)=2-0.1875=1.8125$.`),
      b('The covariance falls below 2, consistent with conditioning on extra future information; this conclusion is specific to this valid Gaussian update.','Covariance giảm từ 2, phù hợp với việc điều kiện hóa thêm thông tin tương lai; kết luận này áp dụng cho bước cập nhật Gaussian hợp lệ này.'),
    ],
    companions: [
      {prompt:b(String.raw`A scalar smoother has $m_{t|t}=-1$, $m_{t+1|t}=2$, $m_{t+1|T}=3$, and $J_t=0.4$. Find $m_{t|T}$.`,String.raw`Bộ làm trơn vô hướng có $m_{t|t}=-1$, $m_{t+1|t}=2$, $m_{t+1|T}=3$, $J_t=0.4$. Tính $m_{t|T}$.`),solution:[b(String.raw`The future correction is $3-2=1$.`,String.raw`Hiệu chỉnh tương lai là $3-2=1$.`),b(String.raw`Multiply by the gain: $0.4(1)=0.4$.`,String.raw`Nhân với gain: $0.4(1)=0.4$.`),b(String.raw`Add it to the filtered mean: $m_{t|T}=-1+0.4=-0.6$.`,String.raw`Cộng vào mean đã lọc: $m_{t|T}=-1+0.4=-0.6$.`)]},
      {prompt:b(String.raw`Given $P_{t|t}=3$, $P_{t+1|t}=5$, $P_{t+1|T}=2$, and scalar $J_t=0.2$, calculate the smoothed variance and say whether it is nonnegative.`,String.raw`Cho $P_{t|t}=3$, $P_{t+1|t}=5$, $P_{t+1|T}=2$, và $J_t=0.2$ vô hướng; tính phương sai đã làm trơn và cho biết nó không âm không.`),solution:[b(String.raw`The future covariance correction is $2-5=-3$.`,String.raw`Hiệu chỉnh covariance tương lai là $2-5=-3$.`),b(String.raw`The scalar covariance formula uses $J_t^2=0.04$, so the change is $0.04(-3)=-0.12$.`,String.raw`Công thức covariance vô hướng dùng $J_t^2=0.04$, nên độ đổi là $0.04(-3)=-0.12$.`),b(String.raw`Therefore $P_{t|T}=3-0.12=2.88\ge0$.`,String.raw`Vì vậy $P_{t|T}=3-0.12=2.88\ge0$.`)]},
      {prompt:b(String.raw`Suppose $P_{t|t}=1$, $P_{t+1|t}=2$, $P_{t+1|T}=2$, and $J_t=0.5$. Apply the covariance recursion and interpret its direction.`,String.raw`Giả sử $P_{t|t}=1$, $P_{t+1|t}=2$, $P_{t+1|T}=2$, $J_t=0.5$. Áp dụng truy hồi covariance và diễn giải hướng thay đổi.`),solution:[b(String.raw`The future covariance equals its prediction: $2-2=0$.`,String.raw`Covariance tương lai bằng covariance dự báo: $2-2=0$.`),b(String.raw`The covariance adjustment is $0.5^2(0)=0$.`,String.raw`Độ điều chỉnh covariance là $0.5^2(0)=0$.`),b(String.raw`Thus $P_{t|T}=1+0=1$. Equal predicted and smoothed next-state covariances give no covariance correction.`,String.raw`Vậy $P_{t|T}=1+0=1$. Covariance trạng thái kế tiếp dự báo và làm trơn bằng nhau nên không có hiệu chỉnh covariance.`)]},
    ],
    reviewNote: 'Checked both RTS recursions, the squared scalar gain in the covariance update, the sign of each correction, and the supplied nonnegative covariance outputs; a covariance reduction is not asserted as a universal rule.',
    sourceIds:['o-sarkka'],
  },
  'm2-w081-e2': {
    title:b('Derive the RTS gain from Gaussian conditioning','Suy gain RTS từ Gaussian có điều kiện'),
    prompt:b(String.raw`Given $\operatorname{Cov}(x_t,x_{t+1}\mid y_{1:t})=P_{t|t}F^	op$, derive $J_t$ and the conditional mean of $x_t$ given $x_{t+1}$ and past observations.`,String.raw`Cho $\operatorname{Cov}(x_t,x_{t+1}\mid y_{1:t})=P_{t|t}F^	op$, hãy suy $J_t$ và mean có điều kiện của $x_t$ theo $x_{t+1}$ cùng các quan sát quá khứ.`),
    application:b('The regression coefficient for inferring a previous state from the next one uses the cross-covariance in the correct matrix orientation.','Hệ số hồi quy để suy trạng thái trước từ trạng thái kế tiếp dùng covariance chéo với đúng chiều ma trận.'),
    formula:b(String.raw`If $P_{t+1|t}$ is invertible, $J_t=P_{t|t}F^	op P_{t+1|t}^{-1}$ and $E[x_t\mid x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}-m_{t+1|t})$.`,String.raw`Nếu $P_{t+1|t}$ khả nghịch, $J_t=P_{t|t}F^	op P_{t+1|t}^{-1}$ và $E[x_t\mid x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}-m_{t+1|t})$.`),
    steps:[b('For a jointly Gaussian pair, regress the first vector on the second using cross-covariance times the inverse covariance of the second.','Với cặp Gaussian đồng thời, hồi quy vector thứ nhất theo vector thứ hai bằng covariance chéo nhân nghịch đảo covariance của vector thứ hai.'),b('The state equation gives cross-covariance $P_{t|t}F^\\top$ and next-state covariance $P_{t+1|t}$.','Phương trình trạng thái cho covariance chéo $P_{t|t}F^\\top$ và covariance trạng thái kế tiếp $P_{t+1|t}$.'),
      b('Center the conditioning state at its conditional prediction $m_{t+1|t}$; the inverse requires a nonsingular prediction covariance.','Lấy tâm trạng thái điều kiện tại dự báo có điều kiện $m_{t+1|t}$; phép nghịch đảo đòi covariance dự báo không suy biến.')],
    primarySolution:[b('Condition on the past; the jointly Gaussian pair has means $m_{t|t},m_{t+1|t}$ and cross-covariance $P_{t|t}F^\\top$.','Điều kiện theo quá khứ; cặp Gaussian có mean $m_{t|t},m_{t+1|t}$ và covariance chéo $P_{t|t}F^\\top$.'),b(String.raw`Gaussian regression multiplies this cross-covariance on the right by $P_{t+1|t}^{-1}$, giving $J_t=P_{t|t}F^	op P_{t+1|t}^{-1}$.`,String.raw`Hồi quy Gaussian nhân covariance chéo bên phải với $P_{t+1|t}^{-1}$, cho $J_t=P_{t|t}F^	op P_{t+1|t}^{-1}$.`),b(String.raw`Subtract the predicted next-state mean from the realized conditioning value: $x_{t+1}-m_{t+1|t}$.`,String.raw`Lấy giá trị điều kiện thực tế trừ mean trạng thái kế tiếp được dự báo: $x_{t+1}-m_{t+1|t}$.`),b(String.raw`Therefore $E[x_t\mid x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}-m_{t+1|t})$. If $P_{t+1|t}$ is singular, use a support-restricted Gaussian conditional or a justified generalized inverse.`,String.raw`Vì vậy $E[x_t\mid x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}-m_{t+1|t})$. Nếu $P_{t+1|t}$ suy biến, dùng phân phối Gaussian có điều kiện trên support hoặc nghịch đảo tổng quát có biện minh.`)],
    companions:[
      {prompt:b(String.raw`In a scalar model, $P_{t|t}=2$, $F=0.8$, $Q=0.5$, $m_{t|t}=1$, $m_{t+1|t}=2$, and the observed conditioning value is $x_{t+1}=2.5$. Compute $J_t$ and the conditional mean.`,String.raw`Trong mô hình vô hướng, $P_{t|t}=2$, $F=0.8$, $Q=0.5$, $m_{t|t}=1$, $m_{t+1|t}=2$, giá trị điều kiện quan sát được là $x_{t+1}=2.5$. Tính $J_t$ và mean có điều kiện.`),solution:[b(String.raw`The next predicted variance is $P_{t+1|t}=F^2P_{t|t}+Q=0.64(2)+0.5=1.78$.`,String.raw`Phương sai dự báo kế tiếp là $P_{t+1|t}=F^2P_{t|t}+Q=0.64(2)+0.5=1.78$.`),b(String.raw`The cross-covariance is $P_{t|t}F=1.6$, so $J_t=1.6/1.78=80/89$.`,String.raw`Covariance chéo là $P_{t|t}F=1.6$, nên $J_t=1.6/1.78=80/89$.`),b(String.raw`The conditioning innovation equals $2.5-2=0.5$; the conditional mean is $1+(80/89)(0.5)=129/89\approx1.4494$.`,String.raw`Innovation điều kiện là $2.5-2=0.5$; mean có điều kiện là $1+(80/89)(0.5)=129/89\approx1.4494$.`)]},
      {prompt:b(String.raw`For jointly Gaussian scalars $X,Y$ with $\operatorname{Cov}(X,Y)=3$ and $\operatorname{Var}(Y)=4$, write the regression gain and conditional mean if $E[X]=2,E[Y]=-1,Y=1$.`,String.raw`Với các biến Gaussian vô hướng đồng thời $X,Y$ có $\operatorname{Cov}(X,Y)=3$, $\operatorname{Var}(Y)=4$, hãy viết gain hồi quy và mean có điều kiện nếu $E[X]=2,E[Y]=-1,Y=1$.`),solution:[b(String.raw`The Gaussian regression gain is $J=\operatorname{Cov}(X,Y)/\operatorname{Var}(Y)=3/4$.`,String.raw`Gain hồi quy Gaussian là $J=\operatorname{Cov}(X,Y)/\operatorname{Var}(Y)=3/4$.`),b(String.raw`The conditioning innovation is $1-(-1)=2$.`,String.raw`Innovation điều kiện là $1-(-1)=2$.`),b(String.raw`Thus $E[X\mid Y=1]=2+(3/4)(2)=3.5$.`,String.raw`Vậy $E[X\mid Y=1]=2+(3/4)(2)=3.5$.`)]},
      {prompt:b(String.raw`Let $X=Z$ and $Y=2Z$ for $Z\sim N(0,1)$. Although the joint covariance is singular, find $E[X\mid Y=y]$ and explain which covariance must be invertible.`,String.raw`Cho $X=Z$ và $Y=2Z$ với $Z\sim N(0,1)$. Dù covariance đồng thời suy biến, hãy tìm $E[X\mid Y=y]$ và giải thích phương sai nào được nghịch đảo.`),solution:[b(String.raw`Here $\operatorname{Var}(Y)=4$ is actually positive, so the scalar conditioning formula is available.`,String.raw`Ở đây $\operatorname{Var}(Y)=4$ dương, nên công thức điều kiện vô hướng vẫn áp dụng được.`),b(String.raw`The gain is $\operatorname{Cov}(X,Y)/\operatorname{Var}(Y)=2/4=1/2$.`,String.raw`Gain bằng $\operatorname{Cov}(X,Y)/\operatorname{Var}(Y)=2/4=1/2$.`),b(String.raw`Since the relationship is exact, $E[X\mid Y=y]=0+(1/2)y=y/2$ and the conditional variance is zero; this illustrates a singular joint law without a singular conditioning covariance.`,String.raw`Do quan hệ là chính xác, $E[X\mid Y=y]=0+(1/2)y=y/2$ và phương sai có điều kiện bằng không; đây là phân phối đồng thời suy biến nhưng covariance của biến điều kiện không suy biến.`)]},
    ],
    reviewNote:'Checked covariance orientation and matrix dimensions, derived the regression coefficient under joint Gaussianity, and distinguished a singular joint law from a singular covariance of the conditioning vector.',sourceIds:['o-sarkka'],
  },
  'm2-w081-e3': {
    title:b('Observability and detectability','Tính quan sát và khả phát hiện'),
    prompt:b(String.raw`For $F=\operatorname{diag}(0.5,1.2)$ and $H=[1,0]$, identify the unobservable eigenmode and determine detectability using the discrete-time definition.`,String.raw`Với $F=\operatorname{diag}(0.5,1.2)$ và $H=[1,0]$, hãy xác định mode riêng không quan sát được và xét khả phát hiện theo định nghĩa thời gian rời rạc.`),
    application:b('An unmeasured state component can grow without bound even while the measured component is estimated accurately.','Thành phần trạng thái không đo được có thể tăng không giới hạn dù thành phần được đo được ước lượng chính xác.'),
    formula:b(String.raw`The observability rows are $H,HF,HF^2,\ldots$; detectability requires every unobservable eigenmode of $F$ to satisfy $|\lambda|<1$.`,String.raw`Các hàng quan sát là $H,HF,HF^2,\ldots$; khả phát hiện yêu cầu mọi mode riêng không quan sát được của $F$ thỏa $|\lambda|<1$.`),
    steps:[b(String.raw`Compute $HF^k$ to see which state coordinates appear in all observations.`,String.raw`Tính $HF^k$ để thấy tọa độ trạng thái nào xuất hiện trong mọi quan sát.`),b(String.raw`Find eigenvalues associated with any unobserved coordinate.`,String.raw`Tìm trị riêng gắn với tọa độ không quan sát được.`),b(String.raw`Compare the modulus of each hidden eigenvalue with one; detectability permits hidden stable modes but not hidden unstable or unit-root modes.`,String.raw`So modulus mỗi trị riêng ẩn với một; khả phát hiện cho phép mode ẩn ổn định nhưng không cho phép mode ẩn bất ổn hoặc có nghiệm đơn vị.`)],
    primarySolution:[b(String.raw`For every integer $k\ge0$, $F^k=\operatorname{diag}(0.5^k,1.2^k)$, hence $HF^k=[0.5^k,0]$.`,String.raw`Với mọi số nguyên $k\ge0$, $F^k=\operatorname{diag}(0.5^k,1.2^k)$, nên $HF^k=[0.5^k,0]$.`),b('The second coordinate never enters any output, so its eigenmode is unobservable; the first coordinate is observed.','Tọa độ thứ hai không xuất hiện trong bất kỳ đầu ra nào nên mode của nó không quan sát được; tọa độ thứ nhất được quan sát.'),b(String.raw`The hidden eigenvalue is $1.2$, with modulus greater than one.`,String.raw`Trị riêng ẩn là $1.2$, có modulus lớn hơn một.`),b('Therefore the pair is not detectable: its unobservable mode is unstable.','Vì vậy cặp này không khả phát hiện: mode không quan sát được là bất ổn.')],
    companions:[
      {prompt:b(String.raw`Let $F=\operatorname{diag}(1.1,0.7)$ and $H=[1,0]$. Is the pair observable? Is it detectable? Justify both answers.`,String.raw`Cho $F=\operatorname{diag}(1.1,0.7)$ và $H=[1,0]$. Cặp này có quan sát được không? Có khả phát hiện không? Biện minh cả hai.`),solution:[b(String.raw`The observability rows are $[1,0],[1.1,0],\ldots$, so their rank is one, not two; the pair is not observable.`,String.raw`Các hàng quan sát là $[1,0],[1.1,0],\ldots$, nên hạng bằng một chứ không phải hai; cặp không quan sát được.`),b('The unobservable second mode has eigenvalue 0.7.','Mode thứ hai không quan sát được có trị riêng 0.7.'),b(String.raw`Since $|0.7|<1$, the unobservable mode is stable and the pair is detectable despite not being observable.`,String.raw`Vì $|0.7|<1$, mode không quan sát được ổn định nên cặp khả phát hiện dù không quan sát đầy đủ.`)]},
      {prompt:b(String.raw`A scalar state has $F=1$ and $H=0$. Classify observability and detectability, noting the strict stability boundary.`,String.raw`Trạng thái vô hướng có $F=1$ và $H=0$. Hãy phân loại tính quan sát và khả phát hiện, lưu ý biên ổn định nghiêm ngặt.`),solution:[b(String.raw`Because $H=0$, every row $HF^k$ is zero; no state value is observable.`,String.raw`Vì $H=0$, mọi hàng $HF^k$ đều bằng không; không giá trị trạng thái nào quan sát được.`),b('The hidden eigenvalue is exactly 1, a unit root.','Trị riêng ẩn bằng đúng 1, tức nghiệm đơn vị.'),b(String.raw`Discrete-time detectability requires hidden modes to satisfy $|\lambda|<1$, not $|\lambda|\le1$; therefore this pair is not detectable.`,String.raw`Khả phát hiện rời rạc yêu cầu mode ẩn thỏa $|\lambda|<1$, không phải $|\lambda|\le1$; do đó cặp không khả phát hiện.`)]},
      {prompt:b(String.raw`For $F=\operatorname{diag}(0.3,1.4)$ and $H=[0,1]$, state which mode is hidden and decide whether the system is detectable.`,String.raw`Với $F=\operatorname{diag}(0.3,1.4)$ và $H=[0,1]$, hãy nêu mode nào bị ẩn và quyết định hệ có khả phát hiện không.`),solution:[b(String.raw`Now $HF^k=[0,1.4^k]$, so the first coordinate is invisible and the second is measured.`,String.raw`Lúc này $HF^k=[0,1.4^k]$, nên tọa độ thứ nhất vô hình và tọa độ thứ hai được đo.`),b(String.raw`The unobservable eigenvalue is $0.3$.`,String.raw`Trị riêng không quan sát được là $0.3$.`),b(String.raw`Its modulus is below one, so the hidden mode is stable and the pair is detectable.`,String.raw`Modulus của nó nhỏ hơn một, nên mode ẩn ổn định và cặp khả phát hiện.`)]},
    ],
    reviewNote:'Checked the observability rows for diagonal systems and used the strict discrete-time condition |lambda|<1, including the unit-root boundary and the distinction between observability and detectability.',sourceIds:['o-sarkka'],
  },
  'm2-w081-e4': {
    title:b('Prevent smoothing look-ahead in a backtest','Tránh nhìn trước từ smoothing trong backtest'),
    prompt:b(String.raw`A backtest at date $t$ uses $x_{t|T}$ from a fixed-interval smoother with $T>t$ to size a position for return $t+1$. Explain the leakage and give the valid information set.`,String.raw`Backtest tại ngày $t$ dùng $x_{t|T}$ từ bộ làm trơn khoảng cố định với $T>t$ để định cỡ vị thế cho lợi suất $t+1$. Giải thích rò rỉ và nêu tập thông tin hợp lệ.`),
    application:b('A position chosen before tomorrow’s return cannot use a state estimate revised with tomorrow’s observations.','Vị thế được chọn trước lợi suất ngày mai không thể dùng ước lượng trạng thái đã sửa bằng quan sát ngày mai.'),
    formula:b(String.raw`Filtering uses $x_{t|t}=E[x_t\mid y_{1:t}]$; smoothing uses $x_{t|T}=E[x_t\mid y_{1:T}]$ and includes future data when $T>t$.`,String.raw`Filtering dùng $x_{t|t}=E[x_t\mid y_{1:t}]$; smoothing dùng $x_{t|T}=E[x_t\mid y_{1:T}]$ và chứa dữ liệu tương lai khi $T>t$.`),
    steps:[b('Write the conditioning sets for the state estimate used at each decision time.','Viết tập điều kiện của ước lượng trạng thái dùng ở mỗi thời điểm quyết định.'),b(String.raw`The smoother includes $y_{t+1:T}$, which is unavailable at time $t$.`,String.raw`Bộ làm trơn chứa $y_{t+1:T}$, vốn chưa có tại thời điểm $t$.`),b('Replace it by the filtered estimate and constrain training and parameter selection to past data or an earlier frozen window.','Thay bằng ước lượng đã lọc và giới hạn huấn luyện, chọn tham số vào dữ liệu quá khứ hoặc cửa sổ trước đã đóng băng.')],
    primarySolution:[b(String.raw`By definition, $x_{t|T}$ is conditional on $y_{1:T}$.`,String.raw`Theo định nghĩa, $x_{t|T}$ điều kiện theo $y_{1:T}$.`),b(String.raw`Since $T>t$, this set contains $y_{t+1},\ldots,y_T$, observations not available when the position for return $t+1$ is chosen.`,String.raw`Vì $T>t$, tập dữ liệu chứa $y_{t+1},\ldots,y_T$, các quan sát chưa có lúc chọn vị thế cho lợi suất $t+1$.`),b('That is look-ahead leakage; timestamping the latent state at t does not remove it.','Đó là rò rỉ nhìn trước; gắn timestamp trạng thái ẩn là t không loại bỏ được.'),b(String.raw`Use $x_{t|t}=E[x_t\mid y_{1:t}]$, and fit or tune parameters only from data available by $t$ or from a separately frozen earlier training sample.`,String.raw`Dùng $x_{t|t}=E[x_t\mid y_{1:t}]$, đồng thời chỉ khớp hoặc chỉnh tham số bằng dữ liệu có tới $t$ hoặc mẫu huấn luyện trước đó được đóng băng riêng.`)],
    companions:[
      {prompt:b(String.raw`An analyst reports the smoothed estimate $x_{40|60}$ as the signal used to trade at date 40. Specify precisely which observations make the report unusable in real time and give the replacement.`,String.raw`Nhà phân tích báo cáo ước lượng làm trơn $x_{40|60}$ làm tín hiệu giao dịch ngày 40. Nêu chính xác quan sát nào khiến báo cáo không dùng được thời gian thực và đưa cách thay.`),solution:[b(String.raw`The estimate conditions on $y_1,\ldots,y_{60}$.`,String.raw`Ước lượng điều kiện theo $y_1,\ldots,y_{60}$.`),b(String.raw`In particular $y_{41},\ldots,y_{60}$ arrive after date 40, so using the signal then leaks future information.`,String.raw`Cụ thể $y_{41},\ldots,y_{60}$ đến sau ngày 40, nên dùng tín hiệu này gây rò rỉ dữ liệu tương lai.`),b(String.raw`Use the filtered state $x_{40|40}=E[x_{40}\mid y_{1:40}]$ and ensure model fitting also respects the date-40 cutoff.`,String.raw`Dùng trạng thái đã lọc $x_{40|40}=E[x_{40}\mid y_{1:40}]$ và bảo đảm khớp mô hình cũng tuân thủ mốc ngày 40.`)]},
      {prompt:b(String.raw`At month end $t$, a model chooses a hedge with $x_{t|t}$ but its parameters were estimated using observations through $t+6$. Is the decision fully real-time? State a valid repair.`,String.raw`Cuối tháng $t$, mô hình chọn hedge bằng $x_{t|t}$ nhưng tham số được ước lượng bằng quan sát đến $t+6$. Quyết định đã hoàn toàn thời gian thực chưa? Nêu cách sửa.`),solution:[b('The filtered state itself uses only data through t, but that does not cure future information entering the fitted parameters.','Bản thân trạng thái đã lọc chỉ dùng dữ liệu đến t, nhưng điều đó không khắc phục việc dữ liệu tương lai đi vào tham số đã khớp.'),b(String.raw`Using $y_{t+1:t+6}$ to estimate parameters makes the decision depend on information unavailable at $t$.`,String.raw`Dùng $y_{t+1:t+6}$ để ước lượng tham số khiến quyết định phụ thuộc thông tin chưa có tại $t$.`),b('Re-estimate using only data through t, or apply parameters selected in a training window that ended before t and was frozen before evaluation.','Ước lượng lại chỉ bằng dữ liệu đến t, hoặc dùng tham số chọn trong cửa sổ huấn luyện kết thúc trước t và được khóa trước đánh giá.') ]},
      {prompt:b(String.raw`A retrospective report estimates $E[x_{25}\mid y_{1:25}]$ after observing data through 25. Is this value a smoother or filter at time 25, and could it have been used to make a decision at time 20?`,String.raw`Báo cáo hồi cứu sau khi có dữ liệu đến 25 tính $E[x_{25}\mid y_{1:25}]$. Đây là smoother hay filter tại 25, và có thể dùng nó ra quyết định tại 20 không?`),solution:[b(String.raw`The target and last conditioning time are both 25, so this is the filtered estimate $x_{25|25}$.`,String.raw`Thời điểm mục tiêu và thời điểm điều kiện cuối đều là 25, nên đây là ước lượng lọc $x_{25|25}$.`),b('It is not a smoother for its own date, though it is computed retrospectively.','Nó không phải smoother cho chính ngày đó, dù được tính hồi cứu.'),b(String.raw`It could not have been used at time 20 because it requires $y_{21:25}$; a date-20 decision needs an estimate measurable from $y_{1:20}$.`,String.raw`Không thể dùng nó tại thời điểm 20 vì cần $y_{21:25}$; quyết định ngày 20 cần ước lượng đo được theo $y_{1:20}$.`)]},
    ],
    reviewNote:'Checked both the latent-state conditioning set and the separate parameter-fitting information set; a filtered state alone does not guarantee a leakage-free backtest.',sourceIds:['o-sarkka'],
  },
  'm2-w081-e5': {
    title:b('A fixed sensor offset and innovation diagnostics','Offset cảm biến cố định và chẩn đoán innovation'),
    prompt:b(String.raw`The true static state is $x=0$ and $y_t=x+5+v_t$, with IID $v_t\sim N(0,1)$. A filter instead uses $y_t=\theta+v_t$ and prior $\theta\sim N(0,1)$. Derive the pre-update $E[r_t]$, its limit, and explain why a post-burn-in innovation histogram cannot identify the offset.`,String.raw`Trạng thái tĩnh thật là $x=0$ và $y_t=x+5+v_t$, với $v_t\sim N(0,1)$ IID. Bộ lọc lại dùng $y_t=\theta+v_t$ và prior $\theta\sim N(0,1)$. Hãy suy $E[r_t]$ trước cập nhật, giới hạn của nó, và giải thích vì sao histogram innovation sau burn-in không nhận diện được offset.`),
    application:b('A static latent level can absorb a constant sensor offset, so residual centering alone does not establish that the measurement equation is correctly calibrated.','Mức ẩn tĩnh có thể hấp thụ offset cảm biến hằng, nên residual được căn tâm không chứng minh phương trình đo đã hiệu chuẩn đúng.'),
    formula:b(String.raw`After $t-1$ unit-variance observations, $m_{t-1}=\sum_{s<t}y_s/t$ and $E[r_t]=5-5(t-1)/t=5/t\to0$.`,String.raw`Sau $t-1$ quan sát phương sai một, $m_{t-1}=\sum_{s<t}y_s/t$ và $E[r_t]=5-5(t-1)/t=5/t\to0$.`),
    steps:[b(String.raw`Combine the unit prior precision with $t-1$ unit observation precisions; the posterior precision is $t$.`,String.raw`Cộng precision prior đơn vị với $t-1$ precision quan sát đơn vị; precision posterior là $t$.`),b(String.raw`The posterior predictive mean is therefore $m_{t-1}=\sum_{s<t}y_s/t$.`,String.raw`Vì vậy mean dự báo posterior là $m_{t-1}=\sum_{s<t}y_s/t$.`),b(String.raw`Use $E[y_s]=5$ to compute the pre-update bias $E[y_t-m_{t-1}]=5/t$.`,String.raw`Dùng $E[y_s]=5$ để tính độ chệch trước cập nhật $E[y_t-m_{t-1}]=5/t$.`),b('Explain that the fitted latent level and sensor offset are not separately identified from this residual sequence without an anchor or calibration.','Giải thích rằng không thể nhận diện riêng mức ẩn đã khớp và offset cảm biến chỉ từ chuỗi residual này nếu thiếu mốc neo hoặc hiệu chuẩn.')],
    primarySolution:[b(String.raw`With prior $\theta\sim N(0,1)$ and observation variance one, after $t-1$ observations the posterior precision is $1+(t-1)=t$.`,String.raw`Với prior $\theta\sim N(0,1)$ và phương sai quan sát một, sau $t-1$ quan sát precision posterior là $1+(t-1)=t$.`),b(String.raw`The posterior mean and next predictive mean are $m_{t-1}=\sum_{s<t}y_s/t$.`,String.raw`Mean posterior và mean dự báo kế tiếp là $m_{t-1}=\sum_{s<t}y_s/t$.`),b(String.raw`Since $E[y_s]=5$, $E[r_t]=5-5(t-1)/t=5/t$, which tends to zero.`,String.raw`Vì $E[y_s]=5$, $E[r_t]=5-5(t-1)/t=5/t$, và giá trị này tiến về không.`),b('The filter can treat the constant offset as a latent level; an approximately centered late-sample histogram cannot distinguish a calibrated state from an offset state. Identification needs a known/anchored state, external sensor calibration, or enough structure to identify state level and offset jointly.','Bộ lọc có thể xem offset hằng như mức ẩn; histogram gần căn tâm ở mẫu muộn không phân biệt được trạng thái hiệu chuẩn với trạng thái bị offset. Muốn nhận diện cần trạng thái đã biết/neo, hiệu chuẩn cảm biến ngoài, hoặc đủ cấu trúc để nhận diện đồng thời mức trạng thái và offset.')],
    companions:[
      {prompt:b(String.raw`A static filter has a unit-variance prior $\theta\sim N(0,1)$ and observes $y_1=4$ with unit noise variance. Find the posterior predictive mean for $y_2$ and the expected pre-update innovation if future observations have mean 4.`,String.raw`Bộ lọc tĩnh có prior $\theta\sim N(0,1)$ phương sai một và quan sát $y_1=4$ với nhiễu phương sai một. Tính mean dự báo $y_2$ và innovation kỳ vọng trước cập nhật nếu các quan sát tương lai có mean 4.`),solution:[b(String.raw`After one observation, posterior precision is $1+1=2$.`,String.raw`Sau một quan sát, precision posterior là $1+1=2$.`),b(String.raw`The posterior mean is $4/2=2$, which is also the predictive mean for $y_2$.`,String.raw`Mean posterior là $4/2=2$, cũng là mean dự báo cho $y_2$.`),b(String.raw`The expected innovation is $4-2=2$; one observation has not yet absorbed the full offset.`,String.raw`Innovation kỳ vọng là $4-2=2$; một quan sát chưa hấp thụ hết offset.`)]},
      {prompt:b(String.raw`Under the same prior and noise variance, suppose the constant observation mean is $c$. Derive $E[r_t]$ before the $t$th update and its rate of decay.`,String.raw`Với cùng prior và phương sai nhiễu, giả sử mean quan sát hằng là $c$. Hãy suy $E[r_t]$ trước cập nhật thứ $t$ và tốc độ giảm của nó.`),solution:[b(String.raw`The posterior precision after $t-1$ observations is $t$, so $m_{t-1}=\sum_{s<t}y_s/t$.`,String.raw`Precision posterior sau $t-1$ quan sát là $t$, nên $m_{t-1}=\sum_{s<t}y_s/t$.`),b(String.raw`Taking expectations gives $E[m_{t-1}]=(t-1)c/t$.`,String.raw`Lấy kỳ vọng được $E[m_{t-1}]=(t-1)c/t$.`),b(String.raw`Therefore $E[r_t]=c-(t-1)c/t=c/t$, which is $O(1/t)$ and approaches zero for fixed $c$.`,String.raw`Do đó $E[r_t]=c-(t-1)c/t=c/t$, có bậc $O(1/t)$ và tiến về không khi $c$ cố định.`)]},
      {prompt:b(String.raw`A late innovation histogram is centered and approximately bell-shaped. Name one untestable explanation from the histogram alone and one extra source of information that could distinguish it.`,String.raw`Histogram innovation muộn được căn tâm và gần hình chuông. Hãy nêu một giải thích không thể kiểm tra chỉ từ histogram và một nguồn thông tin bổ sung giúp phân biệt.`),solution:[b('A constant sensor offset may have been absorbed by the fitted latent level.','Offset cảm biến hằng có thể đã bị mức ẩn khớp hấp thụ.'),b('Centering and shape of residuals alone do not identify the absolute state level or validate the sensor calibration.','Tâm và hình dạng residual riêng không nhận diện mức trạng thái tuyệt đối hay xác nhận hiệu chuẩn cảm biến.'),b('A known reference state, an external calibration measurement, or an identifiable joint model for level and offset provides the missing anchor.','Trạng thái tham chiếu đã biết, phép đo hiệu chuẩn ngoài, hoặc mô hình chung nhận diện được mức và offset sẽ cung cấp mốc neo còn thiếu.') ]},
    ],
    reviewNote:'Checked posterior precision t after t−1 observations, the expected innovation 5/t, and the confounding between static level and measurement offset; histogram shape alone is not treated as an identification result.',sourceIds:['o-sarkka'],
  },
  'm2-w082-e1': {
    title:b('Excess expected log score for normal forecasts','Excess log score kỳ vọng của dự báo chuẩn'),
    prompt:b(String.raw`For true $q=N(0,1)$ and forecast $p=N(1,1)$, compute $KL(q\|p)$, the excess expected negative log score.`,String.raw`Với phân phối thật $q=N(0,1)$ và dự báo $p=N(1,1)$, hãy tính $KL(q\|p)$, tức excess negative log score kỳ vọng.`),
    application:b('A forecast centered one standard deviation from the truth pays an expected logarithmic score penalty measured in nats per observation.','Dự báo lệch tâm một độ lệch chuẩn so với sự thật phải chịu khoản phạt log score kỳ vọng tính bằng nat trên mỗi quan sát.'),
    formula:b(String.raw`For positive variances, $KL(N(\mu_q,\sigma_q^2)\|N(\mu_p,\sigma_p^2))=\frac12[\frac{\sigma_q^2+(\mu_q-\mu_p)^2}{\sigma_p^2}-1+\log(\frac{\sigma_p^2}{\sigma_q^2})]$.`,String.raw`Với phương sai dương, $KL(N(\mu_q,\sigma_q^2)\|N(\mu_p,\sigma_p^2))=\frac12[\frac{\sigma_q^2+(\mu_q-\mu_p)^2}{\sigma_p^2}-1+\log(\frac{\sigma_p^2}{\sigma_q^2})]$.`),
    steps:[b('The expected negative log-score excess under q equals the Kullback–Leibler divergence from q to p.','Excess negative log score lấy kỳ vọng theo q bằng độ phân kỳ Kullback–Leibler từ q đến p.'),b(String.raw`For equal unit variances, the log-determinant terms cancel and only $(\mu_q-\mu_p)^2/2$ remains.`,String.raw`Với phương sai đơn vị bằng nhau, các hạng log định thức triệt tiêu và chỉ còn $(\mu_q-\mu_p)^2/2$.`),b(String.raw`Substitute the mean shift $0-1=-1$ and report the result in nats per forecast.`,String.raw`Thế độ lệch mean $0-1=-1$ và báo kết quả theo nat trên mỗi dự báo.`)],
    primarySolution:[b(String.raw`Under $q=N(0,1)$ and $p=N(1,1)$, the variances match, so the equal-variance formula applies.`,String.raw`Với $q=N(0,1)$ và $p=N(1,1)$, hai phương sai bằng nhau nên áp dụng công thức cùng phương sai.`),b(String.raw`The mean difference is $0-1=-1$.`,String.raw`Chênh lệch mean là $0-1=-1$.`),b(String.raw`Thus $KL(q\|p)=(-1)^2/(2\cdot1)=0.5$ nats.`,String.raw`Vì vậy $KL(q\|p)=(-1)^2/(2\cdot1)=0.5$ nat.`),b('This is the forecast’s excess expected negative log score per draw when q is the true distribution.','Đây là excess negative log score kỳ vọng mỗi lần rút khi q là phân phối thật.')],
    companions:[
      {prompt:b(String.raw`The truth is $N(2,4)$ and a forecast is $N(4,4)$. Find the excess expected log loss.`,String.raw`Phân phối thật là $N(2,4)$ và dự báo là $N(4,4)$. Tính excess log loss kỳ vọng.`),solution:[b(String.raw`The means differ by $2-4=-2$ and the common variance is $4$.`,String.raw`Hai mean chênh $2-4=-2$ và phương sai chung là $4$.`),b(String.raw`For equal variances, $KL=(\mu_q-\mu_p)^2/(2\sigma^2)$.`,String.raw`Với phương sai bằng nhau, $KL=(\mu_q-\mu_p)^2/(2\sigma^2)$.`),b(String.raw`Hence $KL=4/8=0.5$ nats per observation.`,String.raw`Do đó $KL=4/8=0.5$ nat mỗi quan sát.`)]},
      {prompt:b(String.raw`Compare truth $q=N(0,4)$ to forecast $p=N(0,1)$. Compute the KL divergence and identify the variance mismatch cost.`,String.raw`So sánh thật $q=N(0,4)$ với dự báo $p=N(0,1)$. Tính KL và xác định chi phí do lệch phương sai.`),solution:[b(String.raw`The means agree, while $\sigma_q^2=4$ and $\sigma_p^2=1$.`,String.raw`Hai mean giống nhau, còn $\sigma_q^2=4$ và $\sigma_p^2=1$.`),b(String.raw`Substitution gives $KL=\frac12[4-1+\log(1/4)]$.`,String.raw`Thế vào được $KL=\frac12[4-1+\log(1/4)]$.`),b(String.raw`Numerically this is $\frac12(1.613706)=0.806853$ nats; the nonzero cost is entirely due to the forecast being too narrow.`,String.raw`Giá trị số là $\frac12(1.613706)=0.806853$ nat; chi phí khác không hoàn toàn do dự báo quá hẹp.`)]},
      {prompt:b(String.raw`Let $q=N(2,9)$ and $p=N(1,4)$. Evaluate the directed divergence $KL(q\|p)$ to three decimals.`,String.raw`Cho $q=N(2,9)$ và $p=N(1,4)$. Hãy tính độ phân kỳ có hướng $KL(q\|p)$ đến ba chữ số thập phân.`),solution:[b(String.raw`The variance ratio term and mean term combine as $[9+(2-1)^2]/4=10/4=2.5$.`,String.raw`Hạng tỷ số phương sai và hạng mean gộp thành $[9+(2-1)^2]/4=10/4=2.5$.`),b(String.raw`The bracket is $2.5-1+\log(4/9)\approx1.5-0.810930\approx0.689070$.`,String.raw`Biểu thức trong ngoặc là $2.5-1+\log(4/9)\approx1.5-0.810930\approx0.689070$.`),b(String.raw`Therefore $KL(q\|p)=0.344535\approx0.345$ nats; reversing q and p would produce a different value.`,String.raw`Do đó $KL(q\|p)=0.344535\approx0.345$ nat; đảo q và p sẽ cho giá trị khác.`)]},
    ],
    reviewNote:'Checked the directed KL formula with positive normal variances, confirmed the equal-variance reduction, and numerically evaluated the unequal-variance fixtures with natural logarithms.',sourceIds:['o-scoring'],
  },
  'm2-w082-e2': {
    title:b('Prove nonnegativity and equality for log score','Chứng minh log score không âm và điều kiện đẳng thức'),
    prompt:b(String.raw`Derive nonnegativity of expected log-score excess using $-\log u\ge1-u$, and identify exactly when equality holds.`,String.raw`Hãy suy tính không âm của excess log score kỳ vọng bằng $-\log u\ge1-u$ và xác định chính xác điều kiện đẳng thức.`),
    application:b('A forecast density cannot improve expected log score over the truth; support gaps can make its loss infinite.','Mật độ dự báo không thể cải thiện log score kỳ vọng so với phân phối thật; thiếu support có thể làm loss vô hạn.'),
    formula:b(String.raw`For densities q,p with $q\ll p$ and finite cross-entropy, $E_q[-\log p]-E_q[-\log q]=KL(q\|p)\ge0$; equality holds iff $p=q$ q-a.e.`,String.raw`Với mật độ q,p có $q\ll p$ và cross-entropy hữu hạn, $E_q[-\log p]-E_q[-\log q]=KL(q\|p)\ge0$; đẳng thức khi và chỉ khi $p=q$ q-hầu khắp nơi.`),
    steps:[b(String.raw`Restrict integration to $A=\{y:q(y)>0\}$ and first handle any point where p vanishes while q is positive.`,String.raw`Giới hạn tích phân trên $A=\{y:q(y)>0\}$ và trước hết xử lý điểm p bằng không trong khi q dương.`),b(String.raw`On A apply $-\log(p/q)\ge1-p/q$ and integrate against q.`,String.raw`Trên A áp dụng $-\log(p/q)\ge1-p/q$ rồi lấy tích phân theo q.`),b(String.raw`Use $\int_Aq=1$ and $\int_Ap\le1$; equality requires equality in the pointwise inequality and no forecast mass outside A.`,String.raw`Dùng $\int_Aq=1$ và $\int_Ap\le1$; đẳng thức cần đẳng thức ở bất đẳng thức điểm và dự báo không có khối lượng ngoài A.`)],
    primarySolution:[b('Let A be the set where q is positive. If p vanishes on a subset of A with positive q-mass, then the log-score excess is infinite and is nonnegative.','Gọi A là tập q dương. Nếu p bằng không trên tập con của A có khối lượng q dương thì excess log score vô hạn và do đó không âm.'),b(String.raw`Otherwise, on A set $u=p/q>0$ and apply $-\log u\ge1-u$.`,String.raw`Nếu không, trên A đặt $u=p/q>0$ rồi áp dụng $-\log u\ge1-u$.`),b(String.raw`Integrating yields $KL(q\|p)\ge\int_Aq-\int_Ap=1-\int_Ap\ge0$.`,String.raw`Lấy tích phân được $KL(q\|p)\ge\int_Aq-\int_Ap=1-\int_Ap\ge0$.`),b(String.raw`Equality requires $u=1$ q-a.e. on A and $\int_Ap=1$, so p has no mass outside A and p=q q-a.e.; support restriction cannot be replaced by integrating p over all space before checking A.`,String.raw`Đẳng thức đòi $u=1$ q-hầu khắp nơi trên A và $\int_Ap=1$, nên p không có khối lượng ngoài A và p=q q-hầu khắp nơi; không thể thay tích phân p trên A bằng toàn không gian trước khi kiểm tra support.`)],
    companions:[
      {prompt:b(String.raw`For discrete distributions $q=(3/4,1/4)$ and $p=(1/2,1/2)$, calculate $KL(q\|p)$ and verify it is positive.`,String.raw`Với phân phối rời rạc $q=(3/4,1/4)$ và $p=(1/2,1/2)$, hãy tính $KL(q\|p)$ và kiểm tra nó dương.`),solution:[b(String.raw`Both p probabilities are positive on q’s support, so the divergence is finite.`,String.raw`Cả hai xác suất p đều dương trên support của q nên độ phân kỳ hữu hạn.`),b(String.raw`Compute $KL=\frac34\log(3/2)+\frac14\log(1/2)$.`,String.raw`Tính $KL=\frac34\log(3/2)+\frac14\log(1/2)$.`),b(String.raw`Using $\log(1.5)\approx0.405465$ and $\log(0.5)\approx-0.693147$ gives $0.304099>0$.`,String.raw`Dùng $\log(1.5)\approx0.405465$ và $\log(0.5)\approx-0.693147$ được $0.304099>0$.`)]},
      {prompt:b(String.raw`Take $q=(1,0)$ and $p=(1/2,1/2)$. Compute the KL divergence and explain why forecast mass outside q’s support prevents equality.`,String.raw`Cho $q=(1,0)$ và $p=(1/2,1/2)$. Tính KL và giải thích vì sao khối lượng dự báo ngoài support của q ngăn đẳng thức.`),solution:[b(String.raw`Only the first outcome has positive q-mass, so $KL(q\|p)=1\log(1/(1/2))$.`,String.raw`Chỉ outcome thứ nhất có khối lượng q dương, nên $KL(q\|p)=1\log(1/(1/2))$.`),b(String.raw`The result is $\log2\approx0.693147$.`,String.raw`Kết quả là $\log2\approx0.693147$.`),b('The forecast places half its probability on an outcome impossible under q, so its mass on A is only 1/2 and equality in the support-restricted bound is impossible.','Dự báo đặt một nửa xác suất lên outcome bất khả theo q, nên khối lượng trên A chỉ là 1/2 và không thể đạt đẳng thức của cận giới hạn trên support.') ]},
      {prompt:b(String.raw`Let $q=(1,0)$ and $p=(0.6,0.4)$. Evaluate $KL(q\|p)$ and distinguish finiteness from equality.`,String.raw`Cho $q=(1,0)$ và $p=(0.6,0.4)$. Tính $KL(q\|p)$ và phân biệt tính hữu hạn với đẳng thức.`),solution:[b(String.raw`On q’s support A, the only forecast probability used is $p_1=0.6>0$, so the divergence is finite.`,String.raw`Trên support A của q, xác suất dự báo duy nhất được dùng là $p_1=0.6>0$, nên độ phân kỳ hữu hạn.`),b(String.raw`The value is $KL=\log(1/0.6)=\log(5/3)\approx0.510826$.`,String.raw`Giá trị là $KL=\log(1/0.6)=\log(5/3)\approx0.510826$.`),b('It is positive because p is not equal to q and also allocates mass outside A; finite divergence does not imply equality.','Giá trị dương vì p khác q và còn phân bổ khối lượng ngoài A; độ phân kỳ hữu hạn không đồng nghĩa với đẳng thức.') ]},
    ],
    reviewNote:'Checked the support-restricted Gibbs argument, the infinite-divergence case when p=0 on q-positive mass, and equality’s requirement that p place no mass outside q’s support.',sourceIds:['o-scoring'],
  },
  'm2-w082-e3': {
    title:b('Conditional probability integral transform','Biến đổi tích phân xác suất có điều kiện'),
    prompt:b(String.raw`Assume $Y_t\mid\mathcal F_{t-1}$ has a continuous conditional CDF $F_t$. Prove $P(F_t(Y_t)\le u\mid\mathcal F_{t-1})=u$ for $0<u<1$.`,String.raw`Giả sử $Y_t\mid\mathcal F_{t-1}$ có CDF có điều kiện liên tục $F_t$. Chứng minh $P(F_t(Y_t)\le u\mid\mathcal F_{t-1})=u$ với $0<u<1$.`),
    application:b('A continuous conditional forecast should transform its realized observation into a uniform rank, conditional on the information used to issue it.','Dự báo có điều kiện liên tục phải biến quan sát thực tế thành thứ hạng đều khi điều kiện theo thông tin dùng để phát hành forecast.'),
    formula:b(String.raw`If $F_t(y)=P(Y_t\le y\mid\mathcal F_{t-1})$ is conditionally continuous, then $U_t=F_t(Y_t)$ satisfies $P(U_t\le u\mid\mathcal F_{t-1})=u$, $0<u<1$.`,String.raw`Nếu $F_t(y)=P(Y_t\le y\mid\mathcal F_{t-1})$ liên tục có điều kiện thì $U_t=F_t(Y_t)$ thỏa $P(U_t\le u\mid\mathcal F_{t-1})=u$, $0<u<1$.`),
    steps:[b('Condition on the past so the conditional CDF is fixed.','Điều kiện theo quá khứ để CDF có điều kiện trở thành hàm cố định.'),b(String.raw`Choose a conditional quantile $y_u$ with $F_t(y_u)=u$; continuity ensures the transformed sublevel event has probability u.`,String.raw`Chọn phân vị có điều kiện $y_u$ sao cho $F_t(y_u)=u$; tính liên tục bảo đảm biến cố dưới mức của phép biến đổi có xác suất u.`),b(String.raw`Evaluate that event using the conditional CDF. For discrete forecasts, ordinary $F_t(Y_t)$ need not be uniform and requires randomized PIT or a different calibration statement.`,String.raw`Tính xác suất biến cố bằng CDF có điều kiện. Với forecast rời rạc, $F_t(Y_t)$ thông thường không nhất thiết đều và cần PIT ngẫu nhiên hoặc phát biểu hiệu chuẩn khác.`)],
    primarySolution:[b('Condition on $\mathcal F_{t-1}$, which makes $F_t$ a fixed continuous distribution function.','Điều kiện theo $\mathcal F_{t-1}$ khiến $F_t$ trở thành hàm phân phối liên tục cố định.'),b(String.raw`For a given $u\in(0,1)$, continuity supplies a quantile $y_u$ with $F_t(y_u)=u$.`,String.raw`Với $u\in(0,1)$ cho trước, tính liên tục cung cấp phân vị $y_u$ thỏa $F_t(y_u)=u$.`),b(String.raw`The event $\{F_t(Y_t)\le u\}$ equals $\{Y_t\le y_u\}$ up to probability-zero boundary choices.`,String.raw`Biến cố $\{F_t(Y_t)\le u\}$ bằng $\{Y_t\le y_u\}$ đến sai khác ở biên xác suất không.`),b(String.raw`Its conditional probability is $F_t(y_u)=u$, proving conditional uniformity. This argument uses continuity; with jumps the ordinary PIT can have atoms.`,String.raw`Xác suất có điều kiện của biến cố bằng $F_t(y_u)=u$, chứng minh tính đều có điều kiện. Lập luận dùng tính liên tục; nếu có bước nhảy thì PIT thường có thể có nguyên tử.`)],
    companions:[
      {prompt:b(String.raw`Given the past, let $Y\sim N(10,4)$ and observe $Y=12$. Find the PIT value $F(Y)$.`,String.raw`Cho quá khứ, giả sử $Y\sim N(10,4)$ và quan sát $Y=12$. Tính PIT $F(Y)$.`),solution:[b(String.raw`The forecast mean is 10 and the standard deviation is $\sqrt4=2$.`,String.raw`Mean forecast là 10 và độ lệch chuẩn là $\sqrt4=2$.`),b(String.raw`Standardize: $z=(12-10)/2=1$.`,String.raw`Chuẩn hóa: $z=(12-10)/2=1$.`),b(String.raw`Thus $F(12)=\Phi(1)\approx0.8413$; this is the observation’s forecast percentile.`,String.raw`Vậy $F(12)=\Phi(1)\approx0.8413$; đây là phân vị forecast của quan sát.`)]},
      {prompt:b(String.raw`Under a conditional $N(10,4)$ forecast, find the outcome threshold whose conditional PIT is $0.9$ and verify its conditional probability.`,String.raw`Dưới forecast có điều kiện $N(10,4)$, tìm ngưỡng outcome có PIT có điều kiện bằng $0.9$ và kiểm tra xác suất có điều kiện của nó.`),solution:[b(String.raw`The 0.9 standard-normal quantile is $z_{0.9}\approx1.2816$.`,String.raw`Phân vị chuẩn tắc 0.9 là $z_{0.9}\approx1.2816$.`),b(String.raw`Transform back: $y_{0.9}=10+2(1.2816)=12.5632$.`,String.raw`Đổi về thang đo gốc: $y_{0.9}=10+2(1.2816)=12.5632$.`),b(String.raw`By construction $P(Y\le12.5632\mid\mathcal F)=\Phi(1.2816)\approx0.9$, matching the PIT threshold.`,String.raw`Theo cách dựng, $P(Y\le12.5632\mid\mathcal F)=\Phi(1.2816)\approx0.9$, đúng với ngưỡng PIT.`)]},
      {prompt:b(String.raw`A forecast is Bernoulli with $P(Y=0)=P(Y=1)=1/2$. List the possible values of the ordinary PIT $F(Y)$ and explain why the continuous proof does not apply.`,String.raw`Forecast Bernoulli có $P(Y=0)=P(Y=1)=1/2$. Hãy liệt kê các giá trị có thể của PIT thường $F(Y)$) và giải thích vì sao chứng minh liên tục không áp dụng.`),solution:[b(String.raw`The CDF satisfies $F(0)=1/2$ and $F(1)=1$, so $F(Y)$ equals 1/2 or 1, each with probability 1/2.`,String.raw`CDF thỏa $F(0)=1/2$ và $F(1)=1$, nên $F(Y)$ bằng 1/2 hoặc 1, mỗi giá trị xác suất 1/2.`),b('This two-point distribution is not Uniform(0,1); the CDF has jumps and no quantile event argument can fill the gaps.','Phân phối hai điểm này không phải Uniform(0,1); CDF có bước nhảy và lập luận biến cố phân vị không thể lấp các khoảng trống.'),b(String.raw`A randomized PIT can use $U=F(Y^-)+V\{F(Y)-F(Y^- )\}$ with independent $V\sim U(0,1)$ to spread each jump uniformly.`,String.raw`PIT ngẫu nhiên có thể dùng $U=F(Y^-)+V\{F(Y)-F(Y^- )\}$ với $V\sim U(0,1)$ độc lập để trải đều mỗi bước nhảy.`)]},
    ],
    reviewNote:'Checked conditional measurability, continuity and quantile boundary use; the discrete Bernoulli companion explicitly distinguishes ordinary PIT from randomized PIT.',sourceIds:['o-scoring'],
  },
  'm2-w082-e4': {
    title:b('Freeze the forecast before observing its outcome','Đóng băng dự báo trước khi thấy outcome'),
    prompt:b(String.raw`A model issues $F_t$ after observing $Y_t$ and evaluates it on the same $Y_t$. State the violated measurability condition and a valid one-step protocol.`,String.raw`Mô hình phát hành $F_t$ sau khi quan sát $Y_t$ rồi đánh giá trên chính $Y_t$. Hãy nêu điều kiện đo được bị vi phạm và quy trình một bước hợp lệ.`),
    application:b('A forecast cannot be graded fairly if its parameters or distribution can react to the outcome being scored.','Không thể chấm forecast công bằng nếu tham số hoặc phân phối dự báo được phép phản ứng với outcome đang chấm.'),
    formula:b(String.raw`A prequential forecast $F_t$ must be $\mathcal F_{t-1}$-measurable; reveal $Y_t$ only after freezing $F_t$, then score and update.`,String.raw`Forecast prequential $F_t$ phải đo được theo $\mathcal F_{t-1}$; chỉ để lộ $Y_t$ sau khi khóa $F_t$, rồi chấm điểm và cập nhật.`),
    steps:[b('Define the information sigma-field available immediately before the outcome.','Xác định sigma-field thông tin có sẵn ngay trước outcome.'),b('Check that the issued distribution is measurable with respect to that field, not a later field containing the outcome.','Kiểm tra phân phối phát hành đo được theo sigma-field đó chứ không phải sigma-field sau chứa outcome.'),b('Record the frozen forecast, reveal the observation, compute the score, and only then update for the next time.','Ghi lại forecast đã khóa, để lộ quan sát, tính điểm, rồi mới cập nhật cho thời điểm sau.')],
    primarySolution:[b(String.raw`The required condition is that $F_t$ be measurable with respect to pre-outcome information $\mathcal F_{t-1}$.`,String.raw`Điều kiện cần là $F_t$ đo được theo thông tin trước outcome $\mathcal F_{t-1}$.`),b(String.raw`If the model observes $Y_t$ first, the forecast may depend on the value it is supposed to predict, so a log or other score no longer evaluates a genuine prequential forecast.`,String.raw`Nếu mô hình thấy $Y_t$ trước, forecast có thể phụ thuộc giá trị lẽ ra phải dự đoán, nên log score hay score khác không còn đánh giá dự báo prequential thật.`),b('A valid sequence is: construct and freeze F_t from the past, reveal Y_t, score S(F_t,Y_t), and update parameters or state to produce F_{t+1}.','Trình tự hợp lệ là: lập và khóa F_t từ quá khứ, để lộ Y_t, chấm S(F_t,Y_t), rồi cập nhật tham số hoặc trạng thái để tạo F_{t+1}.')],
    companions:[
      {prompt:b(String.raw`At 09:00 a forecaster predicts a daily return. The software recalibrates the forecast distribution using the 16:00 closing return, then logs the 09:00 score. Identify the leakage and an auditable repair.`,String.raw`Lúc 09:00 nhà dự báo dự báo lợi suất ngày. Phần mềm hiệu chỉnh lại phân phối forecast bằng lợi suất đóng cửa 16:00 rồi ghi điểm 09:00. Hãy chỉ ra rò rỉ và cách sửa có thể kiểm toán.`),solution:[b('The 16:00 return is the outcome of the period being forecast, so it is not in the 09:00 information set.','Lợi suất 16:00 là outcome của kỳ đang dự báo nên không thuộc tập thông tin lúc 09:00.'),b('Recalibrating with that return makes the scored distribution outcome-dependent.','Hiệu chỉnh bằng lợi suất đó khiến phân phối được chấm phụ thuộc outcome.'),b('Store the forecast parameters and distribution at 09:00, score that frozen object against the close, and use the close only for forecasts issued later.','Lưu tham số và phân phối forecast lúc 09:00, chấm đúng đối tượng đã khóa với giá đóng cửa, và chỉ dùng giá đóng cửa cho dự báo phát hành sau.') ]},
      {prompt:b(String.raw`A probability forecast for event $A_t$ is issued as $p_t=1$ if $A_t$ occurs and $p_t=0$ otherwise, then evaluated with Brier score. Why is this not a valid forecast and what timing rule fixes it?`,String.raw`Forecast xác suất cho biến cố $A_t$ được phát hành bằng $p_t=1$ nếu $A_t$ xảy ra và $p_t=0$ nếu không, rồi chấm Brier. Vì sao đây không phải forecast hợp lệ và quy tắc thời gian nào sửa được?`),solution:[b('The reported probability is a direct function of the realized event, which was unavailable when a genuine forecast should have been issued.','Xác suất báo cáo là hàm trực tiếp của biến cố đã xảy ra, vốn chưa có khi dự báo thực sự phải được phát hành.'),b('For an outcome-aware choice, Brier loss can be driven to zero mechanically; this says nothing about predictive skill.','Với lựa chọn biết outcome, Brier loss có thể bị ép về không một cách máy móc; điều đó không cho biết năng lực dự báo.'),b(String.raw`Require $p_t$ to be fixed from $\mathcal F_{t-1}$ before observing $1_{A_t}$, then score the recorded probability afterward.`,String.raw`Yêu cầu $p_t$ được xác định từ $\mathcal F_{t-1}$ trước khi thấy $1_{A_t}$, rồi chấm xác suất đã ghi sau đó.`)]},
      {prompt:b(String.raw`A sequential service stores $F_t$, observes $Y_t$, computes a log score, and only then refits for $F_{t+1}$. Check the information timing and state one record needed for reproducibility.`,String.raw`Dịch vụ tuần tự lưu $F_t$, quan sát $Y_t$, tính log score, rồi mới khớp lại cho $F_{t+1}$. Hãy kiểm tra thời điểm thông tin và nêu một bản ghi cần để tái lập.`),solution:[b('The ordering is valid provided the stored F_t was constructed only from information available before Y_t.','Thứ tự hợp lệ nếu F_t được lưu đã tạo chỉ từ thông tin có trước Y_t.'),b('The score is evaluated after revelation and the update affects only the next forecast.','Score được tính sau khi để lộ outcome và cập nhật chỉ ảnh hưởng forecast kế tiếp.'),b('Retain the exact distribution or parameter snapshot, timestamp, and information cutoff used to build F_t so an auditor can reproduce the score.','Giữ bản phân phối hoặc snapshot tham số chính xác, timestamp và mốc dữ liệu dùng để tạo F_t để kiểm toán viên tái lập score.') ]},
    ],
    reviewNote:'Checked the pre-outcome sigma-field, distinguished outcome leakage from permissible post-score updating, and required a frozen forecast record for reproducible evaluation.',sourceIds:['o-scoring'],
  },
  'm2-w082-e5': {
    title:b('Uniform PIT marginals can remain dependent','PIT biên đều vẫn có thể phụ thuộc'),
    prompt:b(String.raw`Let $U_t$ alternate between a draw $U$ and $1-U$, where $U\sim\operatorname{Uniform}(0,1)$. Explain why each marginal is uniform but a PIT histogram misses serial dependence.`,String.raw`Cho $U_t$ luân phiên giữa một lần rút $U$ và $1-U$, với $U\sim\operatorname{Uniform}(0,1)$. Giải thích vì sao từng phân phối biên đều nhưng histogram PIT bỏ sót phụ thuộc chuỗi.`),
    application:b('A forecast calibration histogram checks pooled marginal ranks but cannot establish that successive forecast errors are independent.','Histogram hiệu chuẩn forecast kiểm tra thứ hạng biên gộp nhưng không chứng minh sai số forecast liên tiếp độc lập.'),
    formula:b(String.raw`Both $U$ and $1-U$ are Uniform$(0,1)$, yet $U_{t+1}=1-U_t$ and $\operatorname{Corr}(U_t,U_{t+1})=-1$.`,String.raw`Cả $U$ lẫn $1-U$ đều Uniform$(0,1)$, nhưng $U_{t+1}=1-U_t$ và $\operatorname{Corr}(U_t,U_{t+1})=-1$.`),
    steps:[b('Use reflection invariance of the uniform distribution to check each one-time marginal.','Dùng tính bất biến qua phép phản chiếu của phân phối đều để kiểm tra từng biên theo thời gian.'),b(String.raw`Use the deterministic relation $U_{t+1}=1-U_t$ to expose dependence.`,String.raw`Dùng quan hệ xác định $U_{t+1}=1-U_t$ để chỉ ra phụ thuộc.`),b('Separate a marginal PIT check from serial, conditional, and regime diagnostics.','Tách kiểm tra PIT biên khỏi chẩn đoán chuỗi, có điều kiện và theo chế độ.')],
    primarySolution:[b(String.raw`If $U\sim U(0,1)$, reflection gives $P(1-U\le u)=P(U\ge1-u)=u$ for $0<u<1$.`,String.raw`Nếu $U\sim U(0,1)$ thì phép phản chiếu cho $P(1-U\le u)=P(U\ge1-u)=u$ với $0<u<1$.`),b('Thus both even and odd positions have uniform marginals, so a pooled PIT histogram can look uniform.','Vì vậy cả vị trí chẵn lẫn lẻ đều có biên uniform nên histogram PIT gộp có thể trông đều.'),b(String.raw`But $U_{t+1}=1-U_t$ exactly. Since $\operatorname{Var}(U)=1/12$ and $\operatorname{Cov}(U,1-U)=-1/12$, their correlation is $-1$.`,String.raw`Nhưng $U_{t+1}=1-U_t$ chính xác. Vì $\operatorname{Var}(U)=1/12$ và $\operatorname{Cov}(U,1-U)=-1/12$, correlation bằng $-1$.`),b('A histogram tests marginals only; a complete check also examines serial dependence and conditional calibration.','Histogram chỉ kiểm tra biên; đánh giá đầy đủ còn xem phụ thuộc chuỗi và hiệu chuẩn có điều kiện.')],
    companions:[
      {prompt:b(String.raw`For $U\sim U(0,1)$ and $V=1-U$, compute $E[U]$, $E[V]$, $\operatorname{Cov}(U,V)$, and their correlation.`,String.raw`Với $U\sim U(0,1)$ và $V=1-U$, hãy tính $E[U]$, $E[V]$, $\operatorname{Cov}(U,V)$ và correlation.`),solution:[b(String.raw`Both variables have mean $1/2$ and variance $1/12$.`,String.raw`Cả hai biến có mean $1/2$ và phương sai $1/12$.`),b(String.raw`$E[UV]=E[U-U^2]=1/2-1/3=1/6$, so covariance is $1/6-(1/2)^2=-1/12$.`,String.raw`$E[UV]=E[U-U^2]=1/2-1/3=1/6$, nên covariance bằng $1/6-(1/2)^2=-1/12$.`),b(String.raw`Divide by the standard-deviation product $1/12$ to obtain $\operatorname{Corr}(U,V)=-1$.`,String.raw`Chia cho tích độ lệch chuẩn $1/12$ thu được $\operatorname{Corr}(U,V)=-1$.`)]},
      {prompt:b(String.raw`Let $W_t=U$ for odd t and $W_t=1-U$ for even t, with a single $U\sim U(0,1)$. Check strict stationarity by comparing finite-dimensional distributions after a one-step shift.`,String.raw`Cho $W_t=U$ nếu t lẻ và $W_t=1-U$ nếu t chẵn, với một $U\sim U(0,1)$. Hãy kiểm tra tính dừng nghiêm ngặt bằng cách so phân phối hữu hạn chiều sau khi dịch một bước.`),solution:[b(String.raw`Any consecutive block alternates between U and 1−U; a one-step shift swaps those two coordinates.`,String.raw`Mọi block liên tiếp luân phiên U và 1−U; dịch một bước đổi chỗ hai tọa độ này.`),b('Let V=1−U. Since V is also uniform, the shifted vector (1−U,U,1−U,...) has the same law as (V,1−V,V,...).','Đặt V=1−U. Vì V cũng uniform, vector đã dịch (1−U,U,1−U,...) có cùng luật với (V,1−V,V,...).'),b(String.raw`The same reflection argument applies to every finite block, so all finite-dimensional distributions are shift-invariant and the process is strictly stationary. Adjacent values remain perfectly dependent with correlation −1.`,String.raw`Lập luận phản chiếu áp dụng cho mọi block hữu hạn nên mọi phân phối hữu hạn chiều bất biến theo dịch và quá trình dừng nghiêm ngặt. Các giá trị kề vẫn phụ thuộc hoàn hảo với correlation −1.`)]},
      {prompt:b(String.raw`Compare the alternating pair $(U,1-U)$ with a pair $(U_1,U_2)$ of independent Uniform$(0,1)$ variables. Which marginal diagnostic agrees and which dependence diagnostic separates them?`,String.raw`So sánh cặp luân phiên $(U,1-U)$ với cặp $(U_1,U_2)$ gồm hai biến Uniform$(0,1)$ độc lập. Chẩn đoán biên nào giống và chẩn đoán phụ thuộc nào phân biệt chúng?`),solution:[b('In both cases, each coordinate is individually Uniform(0,1), so a pooled marginal histogram cannot distinguish them.','Trong cả hai trường hợp, mỗi tọa độ riêng có Uniform(0,1), nên histogram biên gộp không phân biệt được.'),b(String.raw`For the alternating pair, covariance is $-1/12$ and correlation $-1$; for independent uniforms, covariance and correlation are zero.`,String.raw`Với cặp luân phiên, covariance bằng $-1/12$ và correlation $-1$; với uniform độc lập, cả hai bằng không.`),b('A lag or joint-rank diagnostic separates perfect alternating dependence from independence.','Chẩn đoán lag hoặc hạng chung phân biệt phụ thuộc luân phiên hoàn hảo với độc lập.') ]},
    ],
    reviewNote:'Checked reflection invariance and the exact covariance/correlation; the alternating construction is used only as a marginal-calibration counterexample, not as a stationary model.',sourceIds:['o-scoring'],
  },
  'm2-w083-e1': {
    title:b('Covariance from overlapping multi-step labels','Covariance từ nhãn nhiều bước chồng lấn'),
    prompt:b(String.raw`For $R_t=\epsilon_{t+1}+\epsilon_{t+2}+\epsilon_{t+3}$ with IID innovations of variance 2, compute $\operatorname{Var}(R_t)$, the lag-1 and lag-2 covariances, and the long-run variance.`,String.raw`Với $R_t=\epsilon_{t+1}+\epsilon_{t+2}+\epsilon_{t+3}$ và innovation IID phương sai 2, hãy tính $\operatorname{Var}(R_t)$, covariance lag 1, lag 2 và long-run variance.`),
    application:b('Rolling three-day outcomes reuse two or one daily shocks at adjacent origins, so their average contains serial covariance beyond the one-window variance.','Outcome trượt ba ngày dùng lại hai hoặc một shock ngày tại các mốc liền nhau, nên trung bình có covariance chuỗi ngoài phương sai một cửa sổ.'),
    formula:b(String.raw`For $R_t=\sum_{j=1}^h\epsilon_{t+j}$ with IID variance $\sigma^2$, $\gamma(k)=(h-|k|)\sigma^2$ for $|k|<h$, zero otherwise, and $\Omega=h^2\sigma^2$.`,String.raw`Với $R_t=\sum_{j=1}^h\epsilon_{t+j}$, innovation IID phương sai $\sigma^2$, ta có $\gamma(k)=(h-|k|)\sigma^2$ nếu $|k|<h$, bằng không nếu khác, và $\Omega=h^2\sigma^2$.`),
    steps:[b('At lag k, count how many innovations appear in both rolling sums.','Ở lag k, đếm số innovation xuất hiện trong cả hai tổng trượt.'),b(String.raw`Multiply that overlap count by $\sigma^2$ to obtain $\gamma(k)$.`,String.raw`Nhân số phần tử chồng lấn với $\sigma^2$ để được $\gamma(k)$.`),b(String.raw`Add lag zero and twice all positive-lag covariances; the triangular sum is $h^2\sigma^2$.`,String.raw`Cộng lag zero và hai lần mọi covariance lag dương; tổng tam giác bằng $h^2\sigma^2$.`)],
    primarySolution:[b(String.raw`Each return has three independent variance-2 innovations, so $\gamma(0)=\operatorname{Var}(R_t)=3(2)=6$.`,String.raw`Mỗi outcome có ba innovation độc lập phương sai 2, nên $\gamma(0)=\operatorname{Var}(R_t)=3(2)=6$.`),b('Adjacent three-step windows share two innovations, hence $\gamma(1)=2(2)=4$.','Hai cửa sổ ba bước kề nhau chia sẻ hai innovation, do đó $\gamma(1)=2(2)=4$.'),b('Windows two steps apart share one innovation, so $\gamma(2)=2$; at lags of at least three they share none.','Cửa sổ cách nhau hai bước chia sẻ một innovation nên $\gamma(2)=2$; từ lag ba trở lên chúng không chung innovation.'),b(String.raw`The long-run variance is $\Omega=6+2(4+2)=18$, three times the marginal variance.`,String.raw`Long-run variance là $\Omega=6+2(4+2)=18$, gấp ba phương sai biên.`)],
    companions:[
      {prompt:b(String.raw`For a two-step rolling sum of IID innovations with variance 3, find its variance, lag-1 covariance, long-run variance, and the model-based $n_{eff}$ when n=120.`,String.raw`Với tổng trượt hai bước từ innovation IID phương sai 3, hãy tìm phương sai, covariance lag 1, long-run variance và $n_{eff}$ theo mô hình khi n=120.`),solution:[b(String.raw`There are two innovations per window, so $\gamma(0)=2(3)=6$; adjacent windows share one, giving $\gamma(1)=3$.`,String.raw`Mỗi cửa sổ có hai innovation nên $\gamma(0)=2(3)=6$; cửa sổ kề chia sẻ một innovation nên $\gamma(1)=3$.`),b(String.raw`Thus $\Omega=6+2(3)=12$.`,String.raw`Vậy $\Omega=6+2(3)=12$.`),b(String.raw`The variance-ratio approximation is $n_{eff}\approx n\gamma(0)/\Omega=120(6/12)=60$, conditional on this overlap model.`,String.raw`Xấp xỉ theo tỷ số phương sai là $n_{eff}\approx n\gamma(0)/\Omega=120(6/12)=60$, với điều kiện đúng mô hình chồng lấn này.`)]},
      {prompt:b(String.raw`A four-day rolling sum uses IID innovations with variance one. List $\gamma(0),\gamma(1),\gamma(2),\gamma(3)$ and compute $\Omega$.`,String.raw`Tổng trượt bốn ngày dùng innovation IID phương sai một. Hãy liệt kê $\gamma(0),\gamma(1),\gamma(2),\gamma(3)$ và tính $\Omega$.`),solution:[b(String.raw`Overlap counts at lags zero through three are 4, 3, 2, and 1, so the covariances have those values.`,String.raw`Số phần tử chồng lấn ở lag từ không đến ba lần lượt là 4, 3, 2, 1, nên covariance cũng lần lượt bằng các giá trị đó.`),b(String.raw`Include both signs for positive lags: $\Omega=4+2(3+2+1)$.`,String.raw`Tính cả hai dấu ở lag dương: $\Omega=4+2(3+2+1)$.`),b(String.raw`Therefore $\Omega=16=h^2\sigma^2=4^2(1)$.`,String.raw`Vậy $\Omega=16=h^2\sigma^2=4^2(1)$.`)]},
      {prompt:b(String.raw`For overlapping $h$-step sums, derive the long-run-to-marginal variance ratio and explain what it says about effective sample size.`,String.raw`Với tổng chồng lấn $h$ bước, hãy suy tỷ số long-run variance trên phương sai biên và giải thích ý nghĩa với cỡ mẫu hiệu dụng.`),solution:[b(String.raw`The marginal variance is $\gamma(0)=h\sigma^2$.`,String.raw`Phương sai biên là $\gamma(0)=h\sigma^2$.`),b(String.raw`Summing the triangular covariance sequence gives $\Omega=h^2\sigma^2$.`,String.raw`Cộng dãy covariance hình tam giác được $\Omega=h^2\sigma^2$.`),b(String.raw`Thus $\Omega/\gamma(0)=h$ and $n_{eff}\approx n\gamma(0)/\Omega=n/h$ for the sample mean under this model, not as a universal rule for other processes.`,String.raw`Do đó $\Omega/\gamma(0)=h$ và $n_{eff}\approx n\gamma(0)/\Omega=n/h$ cho trung bình mẫu theo mô hình này, không phải quy tắc chung cho quá trình khác.`)]},
    ],
    reviewNote:'Checked overlap counts at lags 0–3, the two-sided covariance sum, and the model-specific variance-ratio interpretation of effective sample size.',sourceIds:['o-cmu-mixing'],
  },
  'm2-w083-e2': {
    title:b('Derive the variance of a paired average','Suy phương sai của trung bình ghép cặp'),
    prompt:b(String.raw`Starting from $\bar d_n=n^{-1}\sum_{t=1}^n d_t$, derive $\operatorname{Var}(\bar d_n)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma_d(h)$ and identify the IID special case.`,String.raw`Bắt đầu từ $\bar d_n=n^{-1}\sum_{t=1}^n d_t$, hãy suy $\operatorname{Var}(\bar d_n)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma_d(h)$ và nêu trường hợp IID.`),
    application:b('When comparing forecasts at paired origins, each separation lag contributes according to how many pairs of origins share that lag.','Khi so forecast ở cùng các mốc, mỗi lag khoảng cách đóng góp theo số cặp mốc cách nhau đúng lag đó.'),
    formula:b(String.raw`For weakly stationary $d_t$ with autocovariance $\gamma_d(h)$, $\operatorname{Var}(\bar d_n)=\frac1n\sum_{|h|<n}(1-|h|/n)\gamma_d(h)$; IID leaves $\gamma_d(0)/n$.`,String.raw`Với $d_t$ dừng yếu có autocovariance $\gamma_d(h)$, $\operatorname{Var}(\bar d_n)=\frac1n\sum_{|h|<n}(1-|h|/n)\gamma_d(h)$; IID chỉ còn $\gamma_d(0)/n$.`),
    steps:[b('Expand the variance as the sum of all n squared covariances divided by n squared.','Khai triển phương sai thành tổng covariance của n bình phương cặp, chia n bình phương.'),b('Stationarity groups each pair by lag h, and there are n−|h| pairs at that lag.','Tính dừng gom các cặp theo lag h; ở lag đó có n−|h| cặp.'),b('Factor out 1/n and apply zero autocovariances at nonzero lags only in the IID case.','Đưa 1/n ra ngoài và chỉ dùng covariance khác không ở lag không trong trường hợp IID.')],
    primarySolution:[b(String.raw`Write $\operatorname{Var}(\bar d_n)=n^{-2}\sum_{s=1}^n\sum_{t=1}^n\operatorname{Cov}(d_s,d_t)$.`,String.raw`Viết $\operatorname{Var}(\bar d_n)=n^{-2}\sum_{s=1}^n\sum_{t=1}^n\operatorname{Cov}(d_s,d_t)$.`),b(String.raw`Under weak stationarity, $\operatorname{Cov}(d_s,d_t)=\gamma_d(s-t)$. For each $h$ with $|h|<n$, exactly $n-|h|$ ordered pairs have that lag.`,String.raw`Dưới tính dừng yếu, $\operatorname{Cov}(d_s,d_t)=\gamma_d(s-t)$. Với mỗi $h$ có $|h|<n$, có đúng $n-|h|$ cặp có thứ tự ở lag đó.`),b(String.raw`Thus $\operatorname{Var}(\bar d_n)=n^{-2}\sum_{|h|<n}(n-|h|)\gamma_d(h)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma_d(h)$.`,String.raw`Vì vậy $\operatorname{Var}(\bar d_n)=n^{-2}\sum_{|h|<n}(n-|h|)\gamma_d(h)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma_d(h)$.`),b('If the sequence is IID, all nonzero-lag autocovariances vanish, leaving Var(d_t)/n.','Nếu chuỗi IID, mọi autocovariance lag khác không biến mất, còn lại Var(d_t)/n.')],
    companions:[
      {prompt:b(String.raw`Let n=4, $\gamma(0)=2$, $\gamma(1)=\gamma(-1)=0.5$, and all higher-lag covariances be zero. Compute $\operatorname{Var}(\bar d_4)$.`,String.raw`Cho n=4, $\gamma(0)=2$, $\gamma(1)=\gamma(-1)=0.5$, các covariance lag cao hơn bằng không. Tính $\operatorname{Var}(\bar d_4)$.`),solution:[b(String.raw`Use the lag weights: $\operatorname{Var}(\bar d_4)=\frac14[2+2(1-1/4)(0.5)]$.`,String.raw`Dùng trọng số lag: $\operatorname{Var}(\bar d_4)=\frac14[2+2(1-1/4)(0.5)]$.`),b(String.raw`The lag-one contribution inside brackets is $2(3/4)(0.5)=0.75$.`,String.raw`Đóng góp lag một trong ngoặc là $2(3/4)(0.5)=0.75$.`),b(String.raw`Therefore the variance is $(2+0.75)/4=0.6875$.`,String.raw`Vậy phương sai là $(2+0.75)/4=0.6875$.`)]},
      {prompt:b(String.raw`If $d_t$ is IID with variance 9 and n=25, find the variance and standard error of its sample mean.`,String.raw`Nếu $d_t$ IID phương sai 9 và n=25, hãy tính phương sai và sai số chuẩn của trung bình mẫu.`),solution:[b(String.raw`IID implies $\gamma(h)=0$ for $h\ne0$, so only $\gamma(0)=9$ remains.`,String.raw`IID suy ra $\gamma(h)=0$ khi $h\ne0$, nên chỉ còn $\gamma(0)=9$.`),b(String.raw`The mean variance is $9/25=0.36$.`,String.raw`Phương sai trung bình là $9/25=0.36$.`),b(String.raw`Its standard error is $\sqrt{0.36}=0.6$.`,String.raw`Sai số chuẩn là $\sqrt{0.36}=0.6$.`)]},
      {prompt:b(String.raw`For n=5, suppose only lag 0 and lag ±1 have nonzero autocovariance, with $\gamma(0)=1$ and $\gamma(1)=\gamma(-1)=-0.2$. Compute $n\operatorname{Var}(\bar d_n)$.`,String.raw`Với n=5, giả sử chỉ lag 0 và ±1 có autocovariance khác không, với $\gamma(0)=1$ và $\gamma(1)=\gamma(-1)=-0.2$. Tính $n\operatorname{Var}(\bar d_n)$.`),solution:[b(String.raw`The lag-one Bartlett weight is $1-1/5=0.8$.`,String.raw`Trọng số Bartlett lag một là $1-1/5=0.8$.`),b(String.raw`Thus $n\operatorname{Var}(\bar d_n)=1+2(0.8)(-0.2)=1-0.32$.`,String.raw`Vì vậy $n\operatorname{Var}(\bar d_n)=1+2(0.8)(-0.2)=1-0.32$.`),b(String.raw`The value is $0.68$, below the marginal variance because the adjacent observations are negatively correlated.`,String.raw`Kết quả là $0.68$, thấp hơn phương sai biên vì các quan sát kề có tương quan âm.`)]},
    ],
    reviewNote:'Checked the ordered-pair count n−|h| and both signs for nonzero lags; negative autocovariances are retained rather than truncated.',sourceIds:['o-cmu-mixing'],
  },
  'm2-w083-e3': {
    title:b('A paired mean is not yet an interval','Trung bình ghép cặp chưa phải khoảng tin cậy'),
    prompt:b(String.raw`At five origins, $d=[-2,1,-1,0,-3]$. Compute $\bar d$ and state what additional quantity is required for a dependence-aware interval.`,String.raw`Tại năm mốc, $d=[-2,1,-1,0,-3]$. Hãy tính $\bar d$ và nêu đại lượng bổ sung cần cho khoảng phụ thuộc.`),
    application:b('A short set of paired forecast differences gives a point estimate but does not identify its long-run sampling uncertainty.','Một tập ngắn chênh lệch forecast ghép cặp cho ước lượng điểm nhưng không xác định được bất định lấy mẫu dài hạn.'),
    formula:b(String.raw`$\bar d=n^{-1}\sum_t d_t$; under a justified stationary CLT, $SE(\bar d)\approx\sqrt{\Omega_d/n}$ with $\Omega_d=\sum_h\gamma_d(h)$.`,String.raw`$\bar d=n^{-1}\sum_t d_t$; dưới CLT dừng có biện minh, $SE(\bar d)\approx\sqrt{\Omega_d/n}$ với $\Omega_d=\sum_h\gamma_d(h)$.`),
    steps:[b('Compute the paired average with its sign convention preserved.','Tính trung bình ghép cặp và giữ nguyên quy ước dấu.'),b('Separate the point estimate from the long-run variance needed to quantify dependence.','Tách ước lượng điểm khỏi long-run variance cần để lượng hóa phụ thuộc.'),b('Do not claim an asymptotic interval without enough dependence information and a justified reference limit.','Không khẳng định khoảng tiệm cận khi thiếu thông tin phụ thuộc và giới hạn tham chiếu có biện minh.')],
    primarySolution:[b(String.raw`The values sum to $-2+1-1+0-3=-5$.`,String.raw`Tổng các giá trị là $-2+1-1+0-3=-5$.`),b(String.raw`Dividing by five gives $\bar d=-1$.`,String.raw`Chia cho năm được $\bar d=-1$.`),b('A dependence-aware standard error needs a long-run variance estimate such as a justified HAC estimate, plus assumptions supporting a CLT or another reference distribution.','Sai số chuẩn có xét phụ thuộc cần ước lượng long-run variance như HAC có biện minh, cùng giả thiết hỗ trợ CLT hoặc phân phối tham chiếu khác.'),b('Five observations alone do not establish those conditions or a reliable interval.','Chỉ năm quan sát không chứng minh được các điều kiện đó hay một khoảng đáng tin cậy.')],
    companions:[
      {prompt:b(String.raw`Four paired differences are $[-1,0,2,1]$. Compute the mean and explain why it is not by itself a dependence-aware confidence interval.`,String.raw`Bốn chênh lệch ghép cặp là $[-1,0,2,1]$. Tính mean và giải thích vì sao riêng nó chưa phải khoảng tin cậy có xét phụ thuộc.`),solution:[b(String.raw`Their sum is $-1+0+2+1=2$.`,String.raw`Tổng là $-1+0+2+1=2$.`),b(String.raw`The sample mean is $2/4=0.5$.`,String.raw`Trung bình mẫu là $2/4=0.5$.`),b('An interval also needs the sampling variance of that mean; serial covariance and a suitable limit approximation are not supplied by the mean alone.','Khoảng tin cậy còn cần phương sai lấy mẫu của mean; riêng mean không cung cấp covariance chuỗi hay xấp xỉ giới hạn thích hợp.') ]},
      {prompt:b(String.raw`A sample of paired losses has mean $-0.03$, but the origins are monthly overlapping twelve-month targets. Name the uncertainty estimator and the modeling caution required.`,String.raw`Mẫu loss ghép cặp có mean $-0.03$, nhưng các mốc là target mười hai tháng chồng lấn theo tháng. Hãy nêu ước lượng bất định và lưu ý mô hình cần thiết.`),solution:[b('The negative mean is a point estimate of the paired loss difference under the chosen origin schedule.','Mean âm là ước lượng điểm của chênh lệch loss ghép cặp theo lịch mốc đã chọn.'),b('Use a dependence-aware long-run variance estimator, such as paired HAC with a bandwidth justified for the process.','Dùng ước lượng long-run variance xét phụ thuộc, chẳng hạn HAC ghép cặp với bandwidth có biện minh cho quá trình.'),b('Monthly overlap induces serial dependence; inference also needs a credible stationary/mixing approximation and enough data beyond the twelve-month overlap horizon.','Chồng lấn theo tháng tạo phụ thuộc chuỗi; suy luận còn cần xấp xỉ dừng/mixing đáng tin và dữ liệu đủ dài so với chân trời chồng lấn mười hai tháng.') ]},
      {prompt:b(String.raw`For a paired contrast $d=\ell_A-\ell_B$, an estimated 95% interval is $[-0.08,-0.01]$. State what sign it supports and one limitation that remains.`,String.raw`Với chênh lệch ghép cặp $d=\ell_A-\ell_B$, khoảng 95% ước lượng là $[-0.08,-0.01]$. Nêu dấu mà khoảng hỗ trợ và một giới hạn còn lại.`),solution:[b('Because the entire interval is below zero, it supports a negative mean loss difference for A relative to B under the stated sampling assumptions.','Vì toàn bộ khoảng dưới không, nó hỗ trợ mean chênh lệch loss âm của A so với B dưới các giả thiết lấy mẫu đã nêu.'),b('A negative loss contrast means A has lower average loss, not necessarily higher financial return.','Chênh loss âm nghĩa A có loss trung bình thấp hơn, không nhất thiết lợi suất tài chính cao hơn.'),b('Validity still depends on paired construction, dependence-aware variance estimation, and the reference approximation used for coverage.','Tính hợp lệ vẫn phụ thuộc cách ghép cặp, ước lượng phương sai có xét phụ thuộc và xấp xỉ tham chiếu dùng cho độ phủ.') ]},
    ],
    reviewNote:'Checked the sign convention d=loss A−loss B, the arithmetic mean, and the distinction between a point estimate and an interval requiring long-run variance and a justified limit theorem.',sourceIds:['o-cmu-mixing'],
  },
  'm2-w083-e4': {
    title:b('Statistical forecast gains versus trading claims','Cải thiện dự báo thống kê và tuyên bố giao dịch'),
    prompt:b(String.raw`A model lowers paired mean squared error by 0.02 and the 95% HAC interval for $d=\text{loss}_{new}-\text{loss}_{base}$ is $[-0.04,0.00]$. State the statistical conclusion and two missing elements for a trading-profit claim.`,String.raw`Mô hình giảm mean squared error ghép cặp 0.02 và khoảng HAC 95% cho $d=\text{loss}_{new}-\text{loss}_{base}$ là $[-0.04,0.00]$. Nêu kết luận thống kê và hai yếu tố còn thiếu để khẳng định lợi nhuận giao dịch.`),
    application:b('Forecast accuracy and realized portfolio profit are separate targets because execution timing and costs convert forecasts into cash flows.','Độ chính xác dự báo và lợi nhuận danh mục thực tế là hai mục tiêu khác nhau vì thời điểm thực thi và chi phí biến forecast thành dòng tiền.'),
    formula:b(String.raw`If $d=\ell_{new}-\ell_{base}$, a confidence interval containing 0 does not establish $E[d]<0$ at that confidence level; profit additionally needs a specified trading rule and net-return estimand.`,String.raw`Nếu $d=\ell_{new}-\ell_{base}$, khoảng tin cậy chứa 0 không chứng minh $E[d]<0$ ở mức tin cậy đó; lợi nhuận còn cần quy tắc giao dịch và estimand lợi suất ròng cụ thể.`),
    steps:[b('Interpret the loss-difference sign: a negative value favors the new model.','Diễn giải dấu chênh loss: giá trị âm nghiêng về mô hình mới.'),b('Check whether the reported uncertainty interval excludes zero before claiming a resolved population advantage.','Kiểm tra khoảng bất định có loại không trước khi khẳng định ưu thế quần thể đã phân giải.'),b('List the execution and economic inputs needed to map forecast gains into net trading performance.','Liệt kê đầu vào thực thi và kinh tế cần để chuyển cải thiện dự báo thành hiệu năng giao dịch ròng.')],
    primarySolution:[b(String.raw`The sample mean change is $-0.02$, so its point estimate favors the new model because lower loss is better.`,String.raw`Mức đổi mean mẫu là $-0.02$, nên ước lượng điểm nghiêng về mô hình mới vì loss thấp hơn tốt hơn.`),b(String.raw`The interval $[-0.04,0.00]$ touches zero, so at the stated level it does not establish a strictly negative population mean loss difference.`,String.raw`Khoảng $[-0.04,0.00]$ chạm không, nên ở mức đã nêu nó không chứng minh mean chênh loss quần thể âm nghiêm ngặt.`),b('A profit claim additionally needs a signal-to-position and execution timing rule, as well as transaction costs and a clearly defined risk-adjusted net-return target.','Tuyên bố lợi nhuận còn cần quy tắc chuyển tín hiệu thành vị thế và thời điểm thực thi, cùng chi phí giao dịch và mục tiêu lợi suất ròng điều chỉnh rủi ro được xác định rõ.'),b('Forecast MSE does not encode those portfolio and implementation choices.','Forecast MSE không mã hóa lựa chọn danh mục hay thực thi đó.')],
    companions:[
      {prompt:b(String.raw`For $d=\text{loss}_{A}-\text{loss}_{B}$, suppose the estimated 95% interval is $[-0.12,-0.03]$. What statistical direction is supported, and does this prove a profitable strategy?`,String.raw`Với $d=\text{loss}_{A}-\text{loss}_{B}$, giả sử khoảng 95% ước lượng là $[-0.12,-0.03]$. Hướng thống kê nào được hỗ trợ và điều này có chứng minh chiến lược sinh lời không?`),solution:[b('The entire interval is negative, supporting a lower population mean loss for A relative to B under the interval assumptions.','Toàn bộ khoảng âm, hỗ trợ loss trung bình quần thể của A thấp hơn B dưới giả thiết của khoảng.'),b('This is a forecast-loss conclusion, not a trading-profit conclusion.','Đây là kết luận về loss dự báo, không phải lợi nhuận giao dịch.'),b('A profitable claim needs positions, tradable prices, timing, turnover, costs, and an appropriate net-return/risk analysis.','Tuyên bố sinh lời cần vị thế, giá giao dịch được, thời điểm, turnover, chi phí và phân tích lợi suất ròng/rủi ro phù hợp.') ]},
      {prompt:b(String.raw`A new forecasting model improves mean absolute error, but no trading rule is specified. Identify the estimand actually measured and two quantities needed for an economic comparison.`,String.raw`Mô hình dự báo mới cải thiện mean absolute error nhưng chưa có quy tắc giao dịch. Hãy xác định estimand thực sự được đo và hai đại lượng cần cho so sánh kinh tế.`),solution:[b('The reported estimand is predictive accuracy under the chosen outcome, origins, and loss function.','Estimand được báo cáo là độ chính xác dự báo theo outcome, các mốc và hàm loss đã chọn.'),b('A trading comparison needs a mapping from forecasts to signed positions and the price/time at which those positions can be entered and exited.','So sánh giao dịch cần ánh xạ forecast thành vị thế có dấu và giá/thời điểm có thể vào-ra vị thế.'),b('It also needs realistic costs and a net return or risk-adjusted utility target; lower MAE alone gives neither.','Còn cần chi phí thực tế và mục tiêu lợi suất ròng hoặc utility điều chỉnh rủi ro; MAE thấp hơn riêng lẻ không cung cấp chúng.') ]},
      {prompt:b(String.raw`An HAC interval for the new-minus-base loss difference is $[-0.06,0.02]$. Explain what the sign uncertainty means and why choosing a position after inspecting this interval needs another evaluation step.`,String.raw`Khoảng HAC cho chênh loss mới-trừ-cơ sở là $[-0.06,0.02]$. Giải thích sự không chắc chắn dấu có nghĩa gì và vì sao chọn vị thế sau khi xem khoảng này cần bước đánh giá nữa.`),solution:[b('The interval includes negative and positive values, so it does not resolve whether the new model lowers or raises population loss at the stated level.','Khoảng chứa cả giá trị âm và dương nên chưa phân giải mô hình mới làm giảm hay tăng loss quần thể ở mức đã nêu.'),b('Selecting a strategy after seeing the evaluation interval makes that choice data-dependent and can introduce selection optimism.','Chọn chiến lược sau khi xem khoảng đánh giá khiến lựa chọn phụ thuộc dữ liệu và có thể tạo lạc quan do chọn lọc.'),b('Use a prespecified rule and evaluate it on a separate untouched period, or adjust inference for the model/strategy search.','Dùng quy tắc xác định trước và đánh giá trên giai đoạn riêng chưa đụng tới, hoặc điều chỉnh suy luận cho quá trình tìm mô hình/chiến lược.') ]},
    ],
    reviewNote:'Checked the d sign convention and interval endpoint interpretation; kept statistical loss evidence separate from execution, cost, risk, and post-selection requirements for profit claims.',sourceIds:['o-cmu-mixing'],
  },
  'm2-w083-e5': {
    title:b('Effective information under overlapping labels','Thông tin hiệu dụng với nhãn chồng lấn'),
    prompt:b(String.raw`Compare n=120 IID loss differences with n=120 overlapping 12-step sums of IID innovations. Find approximate IID-equivalent sample sizes under the overlap model and explain why neither count means 120 independent labels.`,String.raw`So sánh n=120 chênh loss IID với n=120 tổng chồng lấn 12 bước từ innovation IID. Hãy tìm cỡ mẫu tương đương IID xấp xỉ theo mô hình chồng lấn và giải thích vì sao số lượng đó không có nghĩa 120 nhãn độc lập.`),
    application:b('Repeated forecast origins can produce many labels while reusing the same underlying daily shocks, lowering information for the average.','Nhiều mốc dự báo có thể tạo nhiều nhãn nhưng dùng lại cùng các shock ngày nền, làm giảm thông tin cho trung bình.'),
    formula:b(String.raw`For overlapping h-step sums, $\gamma(0)=h\sigma^2$, $\Omega=h^2\sigma^2$, and the model-based variance-ratio size is $n_{eff}\approx n\gamma(0)/\Omega=n/h$.`,String.raw`Với tổng chồng lấn h bước, $\gamma(0)=h\sigma^2$, $\Omega=h^2\sigma^2$, và cỡ mẫu theo tỷ số phương sai là $n_{eff}\approx n\gamma(0)/\Omega=n/h$.`),
    steps:[b('For IID single-origin loss differences, the long-run variance equals their marginal variance under the stated model.','Với chênh loss IID theo mốc đơn, long-run variance bằng phương sai biên theo mô hình đã nêu.'),b('For h-step sums, compute the long-run-to-marginal variance inflation factor from overlapping shocks.','Với tổng h bước, tính hệ số phồng long-run variance trên phương sai biên từ các shock chồng lấn.'),b('Report the effective-size ratio as a model-based approximation and retain dependence-aware inference rather than declaring labels independent.','Báo tỷ số cỡ mẫu hiệu dụng như xấp xỉ theo mô hình và giữ suy luận xét phụ thuộc thay vì tuyên bố nhãn độc lập.')],
    primarySolution:[b('The 120 IID loss differences have $n_{eff}=120$ under the given IID assumption.','120 chênh loss IID có $n_{eff}=120$ dưới giả thiết IID đã cho.'),b(String.raw`For h=12 overlapping sums, $\Omega/\gamma(0)=h=12$.`,String.raw`Với tổng chồng lấn h=12, $\Omega/\gamma(0)=h=12$.`),b(String.raw`Thus $n_{eff}\approx120/12=10$ for the sample mean under this specific construction.`,String.raw`Vì vậy $n_{eff}\approx120/12=10$ cho trung bình mẫu dưới cấu trúc cụ thể này.`),b('This is not a universal conversion for arbitrary dependent losses; HAC or another valid dependence model is needed for inference.','Đây không phải phép đổi phổ quát cho loss phụ thuộc tùy ý; suy luận cần HAC hoặc mô hình phụ thuộc hợp lệ khác.')],
    companions:[
      {prompt:b(String.raw`For n=240 overlapping 6-step sums of IID shocks, compute the variance-ratio effective sample size and state its scope.`,String.raw`Với n=240 tổng chồng lấn 6 bước từ shock IID, hãy tính cỡ mẫu hiệu dụng theo tỷ số phương sai và nêu phạm vi của nó.`),solution:[b(String.raw`For h-step sums, the inflation ratio is $\Omega/\gamma(0)=h=6$.`,String.raw`Với tổng h bước, tỷ số phồng là $\Omega/\gamma(0)=h=6$.`),b(String.raw`Therefore $n_{eff}\approx n/h=240/6=40$.`,String.raw`Vậy $n_{eff}\approx n/h=240/6=40$.`),b('This value describes mean-variance information under the specified overlap/IID-shock model, not a general independent-label count.','Giá trị này mô tả thông tin phương sai trung bình theo mô hình shock IID/chồng lấn đã nêu, không phải số nhãn độc lập nói chung.') ]},
      {prompt:b(String.raw`Compare n=100 daily IID observations to n=100 rolling two-day sums of IID shocks. Compute each model-based $n_{eff}$ and explain the contrast.`,String.raw`So sánh n=100 quan sát ngày IID với n=100 tổng trượt hai ngày từ shock IID. Tính $n_{eff}$ theo từng mô hình và giải thích khác biệt.`),solution:[b('For the IID sequence, marginal and long-run variances agree, so effective size is 100.','Với chuỗi IID, phương sai biên và dài hạn bằng nhau nên cỡ hiệu dụng là 100.'),b(String.raw`For two-day sums, the variance inflation factor is $h=2$, giving $n_{eff}\approx100/2=50$.`,String.raw`Với tổng hai ngày, hệ số phồng phương sai là $h=2$, nên $n_{eff}\approx100/2=50$.`),b('The two datasets have the same number of labels but different mean uncertainty because the rolling outcomes reuse innovations.','Hai bộ dữ liệu có cùng số nhãn nhưng bất định trung bình khác nhau vì outcome trượt dùng lại innovation.') ]},
      {prompt:b(String.raw`An analyst replaces n=300 by $n_{eff}=30$ in an IID confidence formula for a nonlinear statistic of overlapping targets. Is the substitution alone a valid proof? Give the required repair.`,String.raw`Nhà phân tích thay n=300 bằng $n_{eff}=30$ trong công thức tin cậy IID cho thống kê phi tuyến của target chồng lấn. Riêng phép thay này có phải chứng minh hợp lệ không? Nêu cách sửa cần thiết.`),solution:[b('No. The variance-ratio effective size for a mean does not establish the tail law of a nonlinear statistic.','Không. Cỡ mẫu hiệu dụng theo tỷ số phương sai cho mean không chứng minh được quy luật đuôi của thống kê phi tuyến.'),b('Overlapping targets induce dependence whose structure and asymptotic behavior must be modeled.','Target chồng lấn tạo phụ thuộc mà cấu trúc và hành vi tiệm cận phải được mô hình hóa.'),b('Use a dependence theorem or block/bootstrap procedure justified for the statistic, target process, and regime; derive the needed variance/rate rather than substituting a guessed n_eff.','Dùng định lý phụ thuộc hoặc block/bootstrap có biện minh cho thống kê, quá trình target và chế độ; suy phương sai/tốc độ cần thay vì thế n_eff phỏng đoán.') ]},
    ],
    reviewNote:'Checked h-step variance inflation and the arithmetic n/h for each fixture; explicitly restricted effective sample size to a variance-ratio interpretation under the named overlap model.',sourceIds:['o-cmu-mixing'],
  },
  'm2-w084-e1': {
    title:b('Long-run variance for overlapping returns','Long-run variance của lợi suất chồng lấn'),
    prompt:b(String.raw`For IID $\epsilon_t$ of variance 1 and $R_t=\epsilon_t+\epsilon_{t+1}$, find $\gamma(0)$, $\gamma(1)$, $\Omega$, and $n_{eff}$ when n=200.`,String.raw`Với $\epsilon_t$ IID phương sai 1 và $R_t=\epsilon_t+\epsilon_{t+1}$, hãy tìm $\gamma(0)$, $\gamma(1)$, $\Omega$ và $n_{eff}$ khi n=200.`),
    application:b('Adjacent two-point returns share one shock, so inference for their mean must include one positive serial covariance.','Lợi suất hai điểm liền nhau chia sẻ một shock nên suy luận cho mean phải tính thêm covariance chuỗi dương lag một.'),
    formula:b(String.raw`With IID innovations of variance $\sigma^2$, $R_t=\epsilon_t+\epsilon_{t+1}$ has $\gamma(0)=2\sigma^2$, $\gamma(1)=\sigma^2$, $\Omega=4\sigma^2$, and $n_{eff}\approx n\gamma(0)/\Omega$.`,String.raw`Với innovation IID phương sai $\sigma^2$, $R_t=\epsilon_t+\epsilon_{t+1}$ có $\gamma(0)=2\sigma^2$, $\gamma(1)=\sigma^2$, $\Omega=4\sigma^2$ và $n_{eff}\approx n\gamma(0)/\Omega$.`),
    steps:[b('Count two independent unit-variance terms in one return.','Đếm hai hạng độc lập phương sai đơn vị trong một lợi suất.'),b(String.raw`At lag one, identify the single shared shock; at greater lags no shocks overlap.`,String.raw`Ở lag một, xác định một shock dùng chung; lag lớn hơn không có shock chồng lấn.`),b('Sum the two-sided covariance sequence and convert the mean-variance ratio to an effective-size approximation.','Cộng dãy covariance hai phía rồi đổi tỷ số phương sai trung bình thành xấp xỉ cỡ hiệu dụng.')],
    primarySolution:[b(String.raw`The return variance is $\gamma(0)=1+1=2$.`,String.raw`Phương sai lợi suất là $\gamma(0)=1+1=2$.`),b(String.raw`Adjacent returns share one unit-variance innovation, so $\gamma(1)=1$; all lags $|h|>1$ have zero covariance.`,String.raw`Lợi suất kề chia sẻ một innovation phương sai đơn vị nên $\gamma(1)=1$; mọi lag $|h|>1$ có covariance bằng không.`),b(String.raw`Therefore $\Omega=\gamma(0)+2\gamma(1)=2+2=4$.`,String.raw`Do đó $\Omega=\gamma(0)+2\gamma(1)=2+2=4$.`),b(String.raw`For n=200, $n_{eff}\approx n\gamma(0)/\Omega=200(2/4)=100$ under this overlap model.`,String.raw`Với n=200, $n_{eff}\approx n\gamma(0)/\Omega=200(2/4)=100$ theo mô hình chồng lấn này.`)],
    companions:[
      {prompt:b(String.raw`If $R_t=\epsilon_t+\epsilon_{t+1}$ with IID innovation variance 4, find its marginal variance, long-run variance, and $n_{eff}$ for n=80.`,String.raw`Nếu $R_t=\epsilon_t+\epsilon_{t+1}$ với innovation IID phương sai 4, hãy tìm phương sai biên, long-run variance và $n_{eff}$ khi n=80.`),solution:[b(String.raw`The two independent terms give $\gamma(0)=4+4=8$.`,String.raw`Hai hạng độc lập cho $\gamma(0)=4+4=8$.`),b(String.raw`One term is shared at lag one, so $\gamma(1)=4$ and $\Omega=8+2(4)=16$.`,String.raw`Một hạng dùng chung ở lag một nên $\gamma(1)=4$ và $\Omega=8+2(4)=16$.`),b(String.raw`Thus $n_{eff}\approx80(8/16)=40$.`,String.raw`Vậy $n_{eff}\approx80(8/16)=40$.`)]},
      {prompt:b(String.raw`For the unit-variance two-point return and n=200, compare the IID and dependence-aware standard errors of its mean.`,String.raw`Với lợi suất hai điểm phương sai innovation bằng một và n=200, hãy so sai số chuẩn IID với sai số chuẩn có xét phụ thuộc của mean.`),solution:[b(String.raw`The IID calculation uses marginal variance 2 and gives $\sqrt{2/200}=0.1$.`,String.raw`Tính IID dùng phương sai biên 2 và cho $\sqrt{2/200}=0.1$.`),b(String.raw`The long-run variance is 4, so the dependence-aware standard error is $\sqrt{4/200}$.`,String.raw`Long-run variance là 4 nên sai số chuẩn có xét phụ thuộc là $\sqrt{4/200}$.`),b(String.raw`This is $0.1414$, larger by $\sqrt2$ because the IID expression omits the shared-shock covariance.`,String.raw`Giá trị là $0.1414$, lớn hơn hệ số $\sqrt2$ vì biểu thức IID bỏ covariance do shock dùng chung.`)]},
      {prompt:b(String.raw`For a stationary process with $\gamma(0)=5$, $\gamma(1)=1$, and all other nonzero-lag covariances zero, find $\Omega$ and approximate $n_{eff}$ for n=250.`,String.raw`Với quá trình dừng có $\gamma(0)=5$, $\gamma(1)=1$ và mọi covariance lag khác không bằng không, hãy tìm $\Omega$ và xấp xỉ $n_{eff}$ khi n=250.`),solution:[b(String.raw`The two-sided covariance sum is $\Omega=5+2(1)=7$.`,String.raw`Tổng covariance hai phía là $\Omega=5+2(1)=7$.`),b(String.raw`The marginal-to-long-run ratio is $5/7$.`,String.raw`Tỷ số biên trên dài hạn là $5/7$.`),b(String.raw`Thus $n_{eff}\approx250(5/7)\approx178.57$, a variance-ratio approximation for this covariance structure.`,String.raw`Vậy $n_{eff}\approx250(5/7)\approx178.57$, là xấp xỉ tỷ số phương sai cho cấu trúc covariance này.`)]},
    ],
    reviewNote:'Checked shared-shock count, two-sided lag sum, standard-error inflation, and variance-ratio effective size.',sourceIds:['o-neweywest'],
  },
  'm2-w084-e2': {
    title:b('Bartlett PSD and a studentized limit','Bartlett PSD và giới hạn studentized'),
    prompt:b(String.raw`(i) Derive $\widehat\Omega_L=[n(L+1)]^{-1}\sum_s b_sb_s^\top$ for zero-padded Bartlett block sums and prove PSD. (ii) For IID fair signs and $d_t=\epsilon_t-\epsilon_{t-1}/2$, derive autocovariances, $n\operatorname{Var}(\bar d_n)$ and $\Omega$. (iii) Under $L\to\infty$, $L^3/n\to0$, justify a studentized limit and explain why PSD alone does not justify coverage.`,String.raw`(i) Suy $\widehat\Omega_L=[n(L+1)]^{-1}\sum_s b_sb_s^\top$ cho tổng block Bartlett đệm không và chứng minh PSD. (ii) Với dấu công bằng IID và $d_t=\epsilon_t-\epsilon_{t-1}/2$, suy autocovariance, $n\operatorname{Var}(\bar d_n)$ và $\Omega$. (iii) Dưới $L\to\infty$, $L^3/n\to0$, biện minh giới hạn studentized và giải thích vì sao PSD riêng lẻ không cho độ phủ.`),
    application:b('A positive-semidefinite HAC estimate is algebraically safe, but statistical coverage also needs consistency and a valid limit law.','Ước lượng HAC nửa xác định dương an toàn đại số, nhưng độ phủ thống kê còn cần tính nhất quán và luật giới hạn hợp lệ.'),
    formula:b(String.raw`Set $b_s=\sum_{j=0}^L z_{s-j}$ with zero padding. Then $a^\top\widehat\Omega_La=[n(L+1)]^{-1}\sum_s(a^\top b_s)^2\ge0$. For $d_t=\epsilon_t-\epsilon_{t-1}/2$, $\gamma(0)=5/4$, $\gamma(\pm1)=-1/2$, $\Omega=1/4$.`,String.raw`Đặt $b_s=\sum_{j=0}^L z_{s-j}$ với đệm không. Khi đó $a^\top\widehat\Omega_La=[n(L+1)]^{-1}\sum_s(a^\top b_s)^2\ge0$. Với $d_t=\epsilon_t-\epsilon_{t-1}/2$, $\gamma(0)=5/4$, $\gamma(\pm1)=-1/2$, $\Omega=1/4$.`),
    steps:[b(String.raw`Expand each block outer product; every pair at lag h is counted $(L+1-|h|)_+$ times, producing Bartlett weights after normalization.`,String.raw`Khai triển tích ngoài mỗi block; mỗi cặp ở lag h được đếm $(L+1-|h|)_+$ lần, cho trọng số Bartlett sau chuẩn hóa.`),b(String.raw`For any vector a the quadratic form is a sum of squares $(a^\top b_s)^2$ times a positive constant, proving PSD.`,String.raw`Với vector a bất kỳ, dạng toàn phương là tổng bình phương $(a^\top b_s)^2$ nhân hằng số dương, chứng minh PSD.`),b('Compute exact lag covariances and finite-n pair weights; then invoke both the selected CLT and the matching HAC consistency result before applying Slutsky.','Tính covariance lag và trọng số cặp hữu hạn n chính xác; rồi viện dẫn cả CLT được chọn lẫn kết quả nhất quán HAC tương ứng trước khi dùng Slutsky.')],
    primarySolution:[b(String.raw`With zero padding and $b_s=\sum_{j=0}^Lz_{s-j}$, expanding $\sum_sb_sb_s^\top$ counts each lag-h pair $(L+1-|h|)_+$ times; division by $n(L+1)$ yields the Bartlett weighted covariance.`,String.raw`Với đệm không và $b_s=\sum_{j=0}^Lz_{s-j}$, khai triển $\sum_sb_sb_s^\top$ đếm mỗi cặp lag h $(L+1-|h|)_+$ lần; chia $n(L+1)$ cho covariance có trọng số Bartlett.`),b(String.raw`For any a, $a^\top\widehat\Omega_La=[n(L+1)]^{-1}\sum_s(a^\top b_s)^2\ge0$, so the matrix is symmetric PSD.`,String.raw`Với a bất kỳ, $a^\top\widehat\Omega_La=[n(L+1)]^{-1}\sum_s(a^\top b_s)^2\ge0$, nên ma trận đối xứng PSD.`),b(String.raw`Fair signs have variance one. Expanding $d_t=\epsilon_t-\epsilon_{t-1}/2$ gives $\gamma(0)=1+1/4=5/4$, $\gamma(\pm1)=-1/2$, and zero covariance at larger lags.`,String.raw`Dấu công bằng có phương sai một. Khai triển $d_t=\epsilon_t-\epsilon_{t-1}/2$ cho $\gamma(0)=1+1/4=5/4$, $\gamma(\pm1)=-1/2$ và covariance bằng không ở lag xa hơn.`),b(String.raw`Pair counting gives $n\operatorname{Var}(\bar d_n)=5/4+2(1-1/n)(-1/2)=1/4+1/n$, hence $\Omega=\sum_h\gamma(h)=1/4>0$.`,String.raw`Đếm cặp cho $n\operatorname{Var}(\bar d_n)=5/4+2(1-1/n)(-1/2)=1/4+1/n$, nên $\Omega=\sum_h\gamma(h)=1/4>0$.`),b('The process is bounded, strictly stationary, and 1-dependent, so the stated mixing CLT applies. The bounded m-dependent HAC theorem with L→∞ and L³/n→0 gives Ω̂_L→pΩ; Slutsky yields asymptotic standard normality of √n(d̄_n−μ)/√Ω̂_L on the event Ω̂_L>0, whose probability tends to one.','Quá trình bị chặn, dừng nghiêm ngặt và 1-phụ thuộc nên CLT mixing đã nêu áp dụng. Định lý nhất quán HAC m-phụ thuộc bị chặn với L→∞ và L³/n→0 cho Ω̂_L→pΩ; Slutsky cho chuẩn tắc tiệm cận của √n(d̄_n−μ)/√Ω̂_L trên biến cố Ω̂_L>0 có xác suất tiến về một.'),b('PSD alone gives neither estimator consistency nor a CLT, finite-sample strict positivity, or interval coverage.','Chỉ PSD không cho tính nhất quán estimator, CLT, tính dương nghiêm ngặt mẫu hữu hạn hay độ phủ khoảng.')],
    companions:[
      {prompt:b(String.raw`For arbitrary zero-padded block sums $b_s$, prove the Bartlett estimate has no negative eigenvalues.`,String.raw`Với tổng block đệm không $b_s$ bất kỳ, hãy chứng minh estimator Bartlett không có trị riêng âm.`),solution:[b('Each outer product b_s b_s^T is symmetric.','Mỗi tích ngoài b_s b_s^T đối xứng.'),b(String.raw`For any a, $a^\top b_sb_s^\top a=(b_s^\top a)^2\ge0$.`,String.raw`Với a bất kỳ, $a^\top b_sb_s^\top a=(b_s^\top a)^2\ge0$.`),b('A positive multiple of a sum of PSD matrices is PSD; a symmetric PSD matrix has only nonnegative eigenvalues.','Bội dương của tổng ma trận PSD vẫn PSD; ma trận đối xứng PSD chỉ có trị riêng không âm.') ]},
      {prompt:b(String.raw`For $d_t=\epsilon_t-\epsilon_{t-1}/2$ with IID variance-one innovations, calculate $n\operatorname{Var}(\bar d_n)$ at n=4 and compare it with $\Omega$.`,String.raw`Với $d_t=\epsilon_t-\epsilon_{t-1}/2$ và innovation IID phương sai một, hãy tính $n\operatorname{Var}(\bar d_n)$ khi n=4 và so với $\Omega$.`),solution:[b(String.raw`The lag covariances are $\gamma(0)=5/4$ and $\gamma(\pm1)=-1/2$.`,String.raw`Covariance lag là $\gamma(0)=5/4$ và $\gamma(\pm1)=-1/2$.`),b(String.raw`At n=4, $n\operatorname{Var}(\bar d_n)=5/4+2(3/4)(-1/2)=1/2$.`,String.raw`Khi n=4, $n\operatorname{Var}(\bar d_n)=5/4+2(3/4)(-1/2)=1/2$.`),b(String.raw`The long-run variance is $\Omega=5/4-1=1/4$; the finite-n scaled variance exceeds it by $1/n=1/4$.`,String.raw`Long-run variance là $\Omega=5/4-1=1/4$; phương sai hữu hạn đã nhân n lớn hơn nó một lượng $1/n=1/4$.`)]},
      {prompt:b(String.raw`Let $x_t=\epsilon_t+\epsilon_{t-1}$ for IID unit-variance noise. A Bartlett estimator with fixed L=0 is PSD. Show its probability limit differs from the true long-run variance.`,String.raw`Cho $x_t=\epsilon_t+\epsilon_{t-1}$ với nhiễu IID phương sai một. Estimator Bartlett bandwidth cố định L=0 là PSD. Hãy chỉ ra giới hạn xác suất khác long-run variance thật.`),solution:[b(String.raw`The marginal variance is $\gamma(0)=2$, while adjacent terms share one shock so $\gamma(1)=1$.`,String.raw`Phương sai biên là $\gamma(0)=2$, còn quan sát kề chia sẻ một shock nên $\gamma(1)=1$.`),b(String.raw`The true long-run variance is $\Omega=2+2(1)=4$.`,String.raw`Long-run variance thật là $\Omega=2+2(1)=4$.`),b('With L=0 only lag-zero variance is retained, so the estimator converges to 2, not 4; PSD does not imply consistency or coverage.','Với L=0 chỉ phương sai lag không được giữ nên estimator hội tụ về 2 chứ không phải 4; PSD không suy ra tính nhất quán hay độ phủ.') ]},
    ],
    reviewNote:'Checked block-sum Bartlett multiplicities, fair-sign covariance and finite-n variance, and stated both CLT and HAC bandwidth conditions; fixed-bandwidth PSD is not called consistent.',sourceIds:['o-neweywest','o-cmu-mixing'],
  },
  'm2-w084-e3': {
    title:b('Finite-n variance and its long-run limit','Phương sai hữu hạn n và giới hạn dài hạn'),
    prompt:b(String.raw`For centered weakly stationary $d_t$, derive $\operatorname{Var}(\bar d_n)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma(h)$ and the long-run variance limit.`,String.raw`Với $d_t$ dừng yếu đã tâm, hãy suy $\operatorname{Var}(\bar d_n)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma(h)$ và giới hạn long-run variance.`),
    application:b('Finite samples taper available covariance lags by pair counts; absolute summability lets that taper approach the full covariance sum.','Mẫu hữu hạn giảm trọng số covariance theo số cặp hiện có; khả tổng tuyệt đối giúp taper tiến đến tổng covariance đầy đủ.'),
    formula:b(String.raw`$\operatorname{Var}(\bar d_n)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma(h)$; if $\sum_h|\gamma(h)|<\infty$, then $n\operatorname{Var}(\bar d_n)\to\Omega=\sum_h\gamma(h)$.`,String.raw`$\operatorname{Var}(\bar d_n)=n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma(h)$; nếu $\sum_h|\gamma(h)|<\infty$ thì $n\operatorname{Var}(\bar d_n)\to\Omega=\sum_h\gamma(h)$.`),
    steps:[b('Expand the variance of the sum and group covariance terms by lag h.','Khai triển phương sai tổng rồi gom các hạng covariance theo lag h.'),b('Count n−|h| ordered pairs at each lag and divide by n squared.','Đếm n−|h| cặp có thứ tự tại mỗi lag rồi chia n bình phương.'),b('Multiply by n and use absolute summability plus dominated convergence to pass to the full lag sum.','Nhân với n rồi dùng khả tổng tuyệt đối cùng hội tụ bị chặn để chuyển sang tổng lag đầy đủ.')],
    primarySolution:[b(String.raw`Stationarity gives $\operatorname{Var}(\bar d_n)=n^{-2}\sum_{s,t=1}^n\gamma(s-t)$.`,String.raw`Tính dừng cho $\operatorname{Var}(\bar d_n)=n^{-2}\sum_{s,t=1}^n\gamma(s-t)$.`),b(String.raw`There are n−|h| pairs at lag h, yielding $n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma(h)$.`,String.raw`Có n−|h| cặp ở lag h, cho $n^{-1}\sum_{|h|<n}(1-|h|/n)\gamma(h)$.`),b(String.raw`After multiplying by n, each fixed-lag weight tends to one and is bounded by one.`,String.raw`Sau khi nhân với n, trọng số mỗi lag cố định tiến đến một và bị chặn trên bởi một.`),b(String.raw`If $\sum_h|\gamma(h)|<\infty$, dominated convergence gives $n\operatorname{Var}(\bar d_n)\to\sum_{h=-\infty}^{\infty}\gamma(h)=\Omega$.`,String.raw`Nếu $\sum_h|\gamma(h)|<\infty$, hội tụ bị chặn cho $n\operatorname{Var}(\bar d_n)\to\sum_{h=-\infty}^{\infty}\gamma(h)=\Omega$.`)],
    companions:[
      {prompt:b(String.raw`For white noise with variance 4, compute $n\operatorname{Var}(\bar d_n)$ for every n and its limit.`,String.raw`Với nhiễu trắng phương sai 4, hãy tính $n\operatorname{Var}(\bar d_n)$ cho mọi n và giới hạn.`),solution:[b(String.raw`White noise has $\gamma(0)=4$ and all nonzero-lag covariances zero.`,String.raw`Nhiễu trắng có $\gamma(0)=4$ và covariance mọi lag khác không bằng không.`),b(String.raw`The finite variance is $\operatorname{Var}(\bar d_n)=4/n$.`,String.raw`Phương sai hữu hạn là $\operatorname{Var}(\bar d_n)=4/n$.`),b(String.raw`Thus $n\operatorname{Var}(\bar d_n)=4$ for each n, and $\Omega=4$.`,String.raw`Vậy $n\operatorname{Var}(\bar d_n)=4$ với mọi n và $\Omega=4$.`)]},
      {prompt:b(String.raw`Suppose only $\gamma(0)=2$ and $\gamma(\pm1)=0.5$ are nonzero. Find $\Omega$ and $n\operatorname{Var}(\bar d_n)$ for n=5.`,String.raw`Giả sử chỉ $\gamma(0)=2$ và $\gamma(\pm1)=0.5$ khác không. Tìm $\Omega$ và $n\operatorname{Var}(\bar d_n)$ khi n=5.`),solution:[b(String.raw`The full sum is $\Omega=2+0.5+0.5=3$.`,String.raw`Tổng đầy đủ là $\Omega=2+0.5+0.5=3$.`),b(String.raw`At n=5 the lag-one weight is 0.8, giving $n\operatorname{Var}(\bar d_n)=2+2(0.8)(0.5)=2.8$.`,String.raw`Khi n=5 trọng số lag một là 0.8, cho $n\operatorname{Var}(\bar d_n)=2+2(0.8)(0.5)=2.8$.`),b('The finite value is below the limit because nonzero lags have fewer available pairs in a short sample.','Giá trị hữu hạn thấp hơn giới hạn vì lag khác không có ít cặp khả dụng hơn trong mẫu ngắn.') ]},
      {prompt:b(String.raw`Explain which assumption lets the Bartlett-tapered covariance sum converge to $\sum_h\gamma(h)$; does that assumption alone prove a CLT?`,String.raw`Giải thích giả thiết nào cho tổng covariance có taper Bartlett hội tụ về $\sum_h\gamma(h)$; riêng giả thiết đó có chứng minh CLT không?`),solution:[b(String.raw`For each fixed h, the weight $(1-|h|/n)_+$ tends to one and remains at most one.`,String.raw`Với h cố định, trọng số $(1-|h|/n)_+$ tiến đến một và luôn không quá một.`),b(String.raw`Absolute summability $\sum_h|\gamma(h)|<\infty$ supplies a summable dominating sequence, so dominated convergence gives the covariance sum.`,String.raw`Khả tổng tuyệt đối $\sum_h|\gamma(h)|<\infty$ cho dãy trội khả tổng, nên hội tụ bị chặn cho tổng covariance.`),b('No. Covariance summability proves this variance limit, but a distributional CLT requires additional dependence and moment conditions.','Không. Khả tổng covariance chứng minh giới hạn phương sai này, nhưng CLT phân phối cần thêm điều kiện phụ thuộc và moment.') ]},
    ],
    reviewNote:'Checked pair counts and two-sided lags; stated absolute covariance summability only for the variance limit and did not infer a CLT from it.',sourceIds:['o-cmu-mixing','o-neweywest'],
  },
  'm2-w084-e4': {
    title:b('Bootstrap paired losses within stable regimes','Bootstrap loss ghép cặp trong chế độ ổn định'),
    prompt:b(String.raw`Paired five-day forecast losses overlap and volatility breaks halfway through the sample. Propose a regime-specific resampling plan and state its inference scope.`,String.raw`Loss forecast ghép cặp năm ngày chồng lấn và volatility đổi chế độ giữa mẫu. Hãy đề xuất kế hoạch tái lấy mẫu theo chế độ và nêu phạm vi suy luận.`),
    application:b('Overlap keeps paired losses serially dependent, and a volatility break makes one stationary block law across the sample questionable.','Chồng lấn giữ cho loss ghép cặp phụ thuộc chuỗi, còn điểm gãy volatility khiến một luật block dừng chung cho cả mẫu trở nên đáng ngờ.'),
    formula:b(String.raw`Resample paired $d_t=\ell_{A,t}-\ell_{B,t}$ blocks wholly inside a prespecified stable regime; block length must reflect dependence and the target is that regime’s mean.`,String.raw`Tái lấy mẫu block ghép cặp $d_t=\ell_{A,t}-\ell_{B,t}$ hoàn toàn trong chế độ ổn định xác định trước; độ dài block phải phản ánh phụ thuộc và estimand là mean chế độ đó.`),
    steps:[b('Form one paired loss difference at every common forecast origin.','Lập một chênh loss ghép cặp tại mọi mốc forecast chung.'),b('Partition at the documented break and never resample a block across regimes.','Chia tại điểm gãy đã ghi nhận và tuyệt đối không tái lấy block xuyên chế độ.'),b('State the within-regime stationarity, dependence and block-length conditions; report an interval for that regime rather than a pooled invariant mean.','Nêu điều kiện dừng, phụ thuộc và độ dài block trong chế độ; báo khoảng cho chế độ đó thay vì mean bất biến gộp.')],
    primarySolution:[b('At each common origin, compute the paired five-day loss contrast so both models are evaluated on the same target.','Ở mỗi mốc chung, tính chênh loss năm ngày ghép cặp để hai mô hình được đánh giá trên cùng target.'),b('Split the paired series at the volatility break, then sample contiguous d-blocks only from the chosen stable segment.','Tách chuỗi ghép cặp tại điểm gãy volatility rồi chỉ lấy các block d liên tiếp từ đoạn ổn định được chọn.'),b('Preserve within-block overlap; justify block length and weak-dependence/stationarity conditions and check that the regime has enough observations.','Bảo toàn chồng lấn trong block; biện minh độ dài block và điều kiện dừng/phụ thuộc yếu, đồng thời kiểm tra chế độ có đủ quan sát.'),b('The resulting inference is regime-specific and does not estimate a single constant law for both volatility regimes.','Suy luận thu được theo chế độ cụ thể và không ước lượng một luật hằng chung cho hai chế độ volatility.')],
    companions:[
      {prompt:b(String.raw`There are 300 paired weekly losses with a documented break after observation 180; inference is requested for the later regime. Specify the bootstrap unit and one scope limitation.`,String.raw`Có 300 loss tuần ghép cặp với điểm gãy sau quan sát 180; cần suy luận cho chế độ sau. Hãy nêu đơn vị bootstrap và một giới hạn phạm vi.`),solution:[b('Create one paired new-minus-base loss difference per weekly origin.','Tạo một chênh loss mới-trừ-cơ-sở ghép cặp cho mỗi mốc tuần.'),b('Draw contiguous blocks only from observations 181–300, with a length chosen to capture within-regime dependence.','Lấy block liên tiếp chỉ từ quan sát 181–300, với độ dài được chọn để nắm phụ thuộc trong chế độ.'),b('The interval targets later-regime performance and says nothing by itself about the earlier regime or a pooled invariant mean.','Khoảng nhắm hiệu năng chế độ sau và riêng nó không nói gì về chế độ trước hay mean bất biến gộp.') ]},
      {prompt:b(String.raw`Two regimes have different paired-loss means $\Delta_1$ and $\Delta_2$. Explain why mixing blocks across their break may target neither regime-specific mean.`,String.raw`Hai chế độ có mean loss ghép cặp khác nhau $\Delta_1$ và $\Delta_2$. Giải thích vì sao trộn block qua điểm gãy có thể không nhắm mean riêng của chế độ nào.`),solution:[b('A stationary block bootstrap treats sampled blocks as draws from one stable dependence distribution.','Bootstrap block dừng xem các block được lấy là mẫu từ một phân phối phụ thuộc ổn định.'),b('A cross-break block combines distinct mean and volatility regimes and inserts artificial transitions.','Block qua điểm gãy kết hợp chế độ mean và volatility khác nhau, đồng thời tạo chuyển tiếp giả.'),b('Its resampled average can be a sample-dependent mixture rather than Δ1 or Δ2; analyze a predeclared regime or model the break explicitly.','Trung bình tái lấy mẫu có thể là hỗn hợp phụ thuộc mẫu chứ không phải Δ1 hay Δ2; hãy phân tích chế độ xác định trước hoặc mô hình hóa điểm gãy tường minh.') ]},
      {prompt:b(String.raw`Within one stable regime, adjacent five-day losses still overlap. What must the paired block bootstrap preserve, and what assumptions are needed for an interval?`,String.raw`Trong một chế độ ổn định, loss năm ngày kề vẫn chồng lấn. Bootstrap block ghép cặp cần bảo toàn gì và cần giả thiết nào để lập khoảng?`),solution:[b('Resample model and baseline losses together through their paired contrast at each origin.','Tái lấy loss mô hình và cơ sở cùng nhau qua chênh ghép cặp tại từng mốc.'),b('Use contiguous blocks to preserve local serial dependence induced by overlapping targets.','Dùng block liên tiếp để bảo toàn phụ thuộc chuỗi cục bộ do target chồng lấn.'),b('Require a stable regime, sufficiently weak dependence for the selected block method, a justified block-length rule, and enough within-regime data.','Cần chế độ ổn định, phụ thuộc đủ yếu cho phương pháp block chọn, quy tắc độ dài block có biện minh và dữ liệu trong chế độ đủ nhiều.') ]},
    ],
    reviewNote:'Checked paired construction, break-respecting resampling, and regime-specific target; overlapping targets require within-block dependence preservation.',sourceIds:['o-neweywest','o-cmu-mixing'],
  },
  'm2-w085-e1': {
    title:b('Approximation, estimation, and returned-iterate errors','Sai số xấp xỉ, ước lượng và điểm lặp trả về'),
    prompt:b(String.raw`Given $R^*=0.10$, $\inf_{f\in\mathcal F}R(f)=0.16$, $R(\hat f)=0.21$, and $R(\tilde f)=0.24$, calculate approximation, estimation, and returned-iterate excess, then verify the total.`,String.raw`Cho $R^*=0.10$, $\inf_{f\in\mathcal F}R(f)=0.16$, $R(\hat f)=0.21$ và $R(\tilde f)=0.24$; tính excess xấp xỉ, ước lượng và điểm trả về rồi kiểm tra tổng.`),
    application:b('A learning system’s final risk separates limitations of the model class, sample-based selection error, and the risk of the actual returned iterate.','Rủi ro cuối của hệ học tách giới hạn của lớp mô hình, sai số chọn theo mẫu và rủi ro của điểm lặp thực sự được trả về.'),
    formula:b(String.raw`$R(\tilde f)-R^*=[\inf_{f\in\mathcal F}R(f)-R^*]+[R(\hat f)-\inf_{f\in\mathcal F}R(f)]+[R(\tilde f)-R(\hat f)]$.`,String.raw`$R(\tilde f)-R^*=[\inf_{f\in\mathcal F}R(f)-R^*]+[R(\hat f)-\inf_{f\in\mathcal F}R(f)]+[R(\tilde f)-R(\hat f)]$.`),
    steps:[b('Insert the best-in-class risk between the global optimum and the empirical ERM.','Chèn risk tốt nhất trong lớp giữa tối ưu toàn cục và ERM thực nghiệm.'),b('Insert and subtract the empirical ERM’s population risk to isolate the returned-iterate term.','Chèn rồi trừ risk quần thể của ERM thực nghiệm để tách hạng điểm trả về.'),b('Compute each adjacent difference and check signs from definitions separately from signs in the numerical fixture.','Tính từng hiệu kề nhau và kiểm tra dấu từ định nghĩa riêng với dấu trong bộ số.')],
    primarySolution:[b(String.raw`Approximation is $0.16-0.10=0.06$.`,String.raw`Xấp xỉ là $0.16-0.10=0.06$.`),b(String.raw`Estimation is $0.21-0.16=0.05$.`,String.raw`Ước lượng là $0.21-0.16=0.05$.`),b(String.raw`Returned-iterate difference is $0.24-0.21=0.03$.`,String.raw`Chênh điểm trả về là $0.24-0.21=0.03$.`),b(String.raw`The sum $0.06+0.05+0.03=0.14$ equals total excess $0.24-0.10=0.14$. This fixture makes the last term positive; a returned approximate empirical minimizer can have a negative population-risk difference from the ERM.`,String.raw`Tổng $0.06+0.05+0.03=0.14$ bằng excess tổng $0.24-0.10=0.14$. Bộ số này làm hạng cuối dương; nghiệm empirical gần đúng được trả về vẫn có thể có chênh risk quần thể âm so với ERM.`)],
    companions:[
      {prompt:b(String.raw`Suppose $R^*=0.08$, best-in-class risk is 0.15, $R(\hat f)=0.20$, and $R(\tilde f)=0.27$. Compute the three terms and check the total.`,String.raw`Giả sử $R^*=0.08$, risk tốt nhất trong lớp là 0.15, $R(\hat f)=0.20$ và $R(\tilde f)=0.27$. Tính ba hạng và kiểm tra tổng.`),solution:[b(String.raw`Approximation is $0.15-0.08=0.07$.`,String.raw`Xấp xỉ là $0.15-0.08=0.07$.`),b(String.raw`Estimation is $0.20-0.15=0.05$, and returned-iterate difference is $0.27-0.20=0.07$.`,String.raw`Ước lượng là $0.20-0.15=0.05$, còn chênh điểm trả về là $0.27-0.20=0.07$.`),b(String.raw`Their sum is $0.19$, matching $R(\tilde f)-R^*=0.27-0.08=0.19$.`,String.raw`Tổng là $0.19$, khớp $R(\tilde f)-R^*=0.27-0.08=0.19$.`)]},
      {prompt:b(String.raw`Let $R^*=0.05$, best-in-class risk 0.12, $R(\hat f)=0.18$, and $R(\tilde f)=0.16$. Compute the decomposition and interpret the sign of the returned-iterate term.`,String.raw`Cho $R^*=0.05$, risk tốt nhất trong lớp 0.12, $R(\hat f)=0.18$ và $R(\tilde f)=0.16$. Tính phép tách và diễn giải dấu của hạng điểm trả về.`),solution:[b(String.raw`Approximation is $0.12-0.05=0.07$ and ERM estimation is $0.18-0.12=0.06$.`,String.raw`Xấp xỉ là $0.12-0.05=0.07$ và ước lượng ERM là $0.18-0.12=0.06$.`),b(String.raw`The returned-iterate difference is $0.16-0.18=-0.02$.`,String.raw`Chênh điểm trả về là $0.16-0.18=-0.02$.`),b(String.raw`Then $0.07+0.06-0.02=0.11=0.16-0.05$. A negative population gap is possible because the optimization condition compares empirical, not population, risks.`,String.raw`Khi đó $0.07+0.06-0.02=0.11=0.16-0.05$. Chênh quần thể âm có thể xảy ra vì điều kiện tối ưu so risk empirical, không phải risk quần thể.`)]},
      {prompt:b(String.raw`Best-in-class risk is 0.30 and returned risk is 0.43; the approximation term is 0.12 and the returned-iterate term is 0.04. Find the ERM estimation term.`,String.raw`Risk tốt nhất trong lớp là 0.30 và risk trả về là 0.43; hạng xấp xỉ là 0.12 và hạng điểm trả về là 0.04. Tìm hạng ước lượng ERM.`),solution:[b(String.raw`The returned-iterate term is $R(\tilde f)-R(\hat f)=0.04$, so $R(\hat f)=0.43-0.04=0.39$.`,String.raw`Hạng điểm trả về là $R(\tilde f)-R(\hat f)=0.04$, nên $R(\hat f)=0.43-0.04=0.39$.`),b(String.raw`Subtract the best-in-class risk: estimation is $0.39-0.30=0.09$.`,String.raw`Trừ risk tốt nhất trong lớp: sai số ước lượng là $0.39-0.30=0.09$.`),b('The approximation term is not needed for this subtraction; it would determine the global optimum only if paired with the class risk consistently.','Hạng xấp xỉ không cần cho phép trừ này; nó chỉ xác định tối ưu toàn cục nếu được ghép nhất quán với risk của lớp.') ]},
    ],
    reviewNote:'Checked the telescoping equality and each numerical subtraction; clarified that only the fixture, not the approximate-ERM definition, makes the returned population gap nonnegative.',sourceIds:['o-cmu705'],
  },
  'm2-w085-e2': {
    title:b('Finite-class Hoeffding deviation radius','Bán kính lệch Hoeffding cho lớp hữu hạn'),
    prompt:b(String.raw`Assume $|\mathcal F|=M<\infty$, $Z_i$ are IID, and $0\le\ell\le1$. From two-sided fixed-f Hoeffding derive $P(\sup_{f\in\mathcal F}|\widehat R-R|>\epsilon)$ and solve for a radius with failure probability at most $\delta$.`,String.raw`Giả sử $|\mathcal F|=M<\infty$, $Z_i$ IID và $0\le\ell\le1$. Từ Hoeffding hai phía cho f cố định, hãy suy $P(\sup_{f\in\mathcal F}|\widehat R-R|>\epsilon)$ và tìm bán kính có xác suất thất bại không quá $\delta$.`),
    application:b('Searching a finite collection of bounded-loss models incurs a logarithmic cost to control all empirical-to-population deviations simultaneously.','Tìm trong một tập hữu hạn mô hình loss bị chặn phải trả chi phí log để khống chế đồng thời mọi độ lệch empirical-population.'),
    formula:b(String.raw`For IID data and $0\le\ell\le1$, $P(\sup_{f\in\mathcal F}|\widehat R(f)-R(f)|>\epsilon)\le2M e^{-2n\epsilon^2}$; $\epsilon=\sqrt{\log(2M/\delta)/(2n)}$ suffices.`,String.raw`Với dữ liệu IID và $0\le\ell\le1$, $P(\sup_{f\in\mathcal F}|\widehat R(f)-R(f)|>\epsilon)\le2M e^{-2n\epsilon^2}$; $\epsilon=\sqrt{\log(2M/\delta)/(2n)}$ là đủ.`),
    steps:[b('Apply two-sided Hoeffding for one fixed f using independent examples and a unit-width loss range.','Áp dụng Hoeffding hai phía cho f cố định với ví dụ độc lập và khoảng loss độ rộng một.'),b('Use a union bound over the M functions to control the supremum.','Dùng cận hợp qua M hàm để khống chế supremum.'),b('Set the tail bound to δ and solve the resulting inequality for ε.','Đặt cận đuôi bằng δ rồi giải bất đẳng thức theo ε.')],
    primarySolution:[b(String.raw`For each fixed f, Hoeffding gives $P(|\widehat R(f)-R(f)|>\epsilon)\le2e^{-2n\epsilon^2}$.`,String.raw`Với từng f cố định, Hoeffding cho $P(|\widehat R(f)-R(f)|>\epsilon)\le2e^{-2n\epsilon^2}$.`),b('Taking a union bound over the M candidates gives a supremum tail at most 2M exp(−2nε²).','Lấy cận hợp qua M ứng viên cho đuôi supremum không quá 2M exp(−2nε²).'),b(String.raw`Require $2M e^{-2n\epsilon^2}\le\delta$, so $\epsilon^2\ge\log(2M/\delta)/(2n)$.`,String.raw`Yêu cầu $2M e^{-2n\epsilon^2}\le\delta$, nên $\epsilon^2\ge\log(2M/\delta)/(2n)$.`),b(String.raw`Thus $\epsilon=\sqrt{\log(2M/\delta)/(2n)}$ controls every candidate with probability at least $1-\delta$, provided IID, bounded loss, and finite M hold.`,String.raw`Vì vậy $\epsilon=\sqrt{\log(2M/\delta)/(2n)}$ khống chế mọi ứng viên với xác suất ít nhất $1-\delta$, khi có IID, loss bị chặn và M hữu hạn.`)],
    companions:[
      {prompt:b(String.raw`For n=100, M=5, and δ=0.1, calculate the finite-class radius.`,String.raw`Với n=100, M=5 và δ=0.1, hãy tính bán kính lớp hữu hạn.`),solution:[b(String.raw`The log argument is $2M/\delta=10/0.1=100$.`,String.raw`Đối số log là $2M/\delta=10/0.1=100$.`),b(String.raw`Then $\epsilon=\sqrt{\log(100)/200}\approx\sqrt{4.605170/200}$.`,String.raw`Khi đó $\epsilon=\sqrt{\log(100)/200}\approx\sqrt{4.605170/200}$.`),b(String.raw`Numerically, $\epsilon\approx0.15174$.`,String.raw`Giá trị số là $\epsilon\approx0.15174$.`)]},
      {prompt:b(String.raw`With n=500, M=10, and δ=0.1, find the radius and state the event it controls.`,String.raw`Với n=500, M=10 và δ=0.1, hãy tìm bán kính và nêu biến cố nó khống chế.`),solution:[b(String.raw`The log argument is $2(10)/0.1=200$ and denominator $2n=1000$.`,String.raw`Đối số log là $2(10)/0.1=200$ và mẫu số $2n=1000$.`),b(String.raw`Compute $\epsilon=\sqrt{\log(200)/1000}\approx\sqrt{5.298317/1000}$.`,String.raw`Tính $\epsilon=\sqrt{\log(200)/1000}\approx\sqrt{5.298317/1000}$.`),b(String.raw`The value is about 0.07279 and it simultaneously bounds the empirical-to-population risk deviations for all ten functions with probability at least 0.9.`,String.raw`Giá trị khoảng 0.07279 và khống chế đồng thời độ lệch risk empirical-population của cả mười hàm với xác suất ít nhất 0.9.`)]},
      {prompt:b(String.raw`For M=1, n=100, and δ=0.05, show that the finite-class radius agrees with the two-sided fixed-function Hoeffding radius.`,String.raw`Với M=1, n=100 và δ=0.05, hãy chỉ ra bán kính lớp hữu hạn trùng bán kính Hoeffding hai phía cho một hàm cố định.`),solution:[b(String.raw`Substitute M=1 to get $\epsilon=\sqrt{\log(2/0.05)/(200)}$.`,String.raw`Thế M=1 được $\epsilon=\sqrt{\log(2/0.05)/(200)}$.`),b('The fixed-function two-sided tail is 2 exp(−2nε²); solving it equal to δ gives exactly the same expression.','Đuôi hai phía hàm cố định là 2 exp(−2nε²); giải bằng δ cho đúng biểu thức này.'),b(String.raw`Numerically $\epsilon=\sqrt{\log40/200}\approx0.13581$, so the finite-class result reduces to the one-function case.`,String.raw`Giá trị số $\epsilon=\sqrt{\log40/200}\approx0.13581$, nên kết quả lớp hữu hạn thu về trường hợp một hàm.`)]},
    ],
    reviewNote:'Checked the two-sided factor 2, the union factor M, natural logarithms, and all IID/bounded/finite-class conditions; M=1 recovers fixed-f Hoeffding.',sourceIds:['o-cmu705'],
  },
  'm2-w085-e3': {
    title:b('Excess risk of an approximate empirical minimizer','Excess risk của nghiệm cực tiểu empirical gần đúng'),
    prompt:b(String.raw`For finite $\mathcal F$, let $\hat f$ minimize $\widehat R$ and suppose $\widehat R(\tilde f)\le\min_f\widehat R(f)+\epsilon_{opt}$. On $\sup_f|\widehat R-R|\le\epsilon$, prove $R(\tilde f)-\min_fR(f)\le2\epsilon+\epsilon_{opt}$.`,String.raw`Với $\mathcal F$ hữu hạn, cho $\hat f$ tối thiểu hóa $\widehat R$ và $\widehat R(\tilde f)\le\min_f\widehat R(f)+\epsilon_{opt}$. Trên biến cố $\sup_f|\widehat R-R|\le\epsilon$, hãy chứng minh $R(\tilde f)-\min_fR(f)\le2\epsilon+\epsilon_{opt}$.`),
    application:b('An optimizer that stops before exact empirical minimization can still be compared with the best population-risk member using a uniform deviation event.','Bộ tối ưu dừng trước khi cực tiểu empirical chính xác vẫn có thể so với phần tử risk quần thể tốt nhất bằng biến cố lệch đồng đều.'),
    formula:b(String.raw`If $\sup_f|\widehat R(f)-R(f)|\le\epsilon$ and $\widehat R(\tilde f)\le\min_f\widehat R(f)+\epsilon_{opt}$, then $R(\tilde f)-\min_fR(f)\le2\epsilon+\epsilon_{opt}$.`,String.raw`Nếu $\sup_f|\widehat R(f)-R(f)|\le\epsilon$ và $\widehat R(\tilde f)\le\min_f\widehat R(f)+\epsilon_{opt}$ thì $R(\tilde f)-\min_fR(f)\le2\epsilon+\epsilon_{opt}$.`),
    steps:[b('Choose a population minimizer, which exists because the class is finite.','Chọn minimizer quần thể, tồn tại vì lớp hữu hạn.'),b('Insert empirical risks at the returned iterate, empirical ERM, and population minimizer to telescope the excess.','Chèn risk empirical tại điểm trả về, ERM empirical và minimizer quần thể để tổng khử excess.'),b('Bound the two population-to-empirical differences by ε, the optimization gap by εopt, and the ERM difference by zero.','Chặn hai chênh population-empirical bởi ε, khoảng tối ưu bởi εopt và chênh ERM bởi không.')],
    primarySolution:[b(String.raw`Finiteness gives $f^*_{\mathcal F}\in\arg\min_{f\in\mathcal F}R(f)$.`,String.raw`Tính hữu hạn cho $f^*_{\mathcal F}\in\arg\min_{f\in\mathcal F}R(f)$.`),b(String.raw`Insert empirical risks: $R(\tilde f)-R(f^*_{\mathcal F})=[R(\tilde f)-\widehat R(\tilde f)]+[\widehat R(\tilde f)-\widehat R(\hat f)]+[\widehat R(\hat f)-\widehat R(f^*_{\mathcal F})]+[\widehat R(f^*_{\mathcal F})-R(f^*_{\mathcal F})]$.`,String.raw`Chèn risk empirical: $R(\tilde f)-R(f^*_{\mathcal F})=[R(\tilde f)-\widehat R(\tilde f)]+[\widehat R(\tilde f)-\widehat R(\hat f)]+[\widehat R(\hat f)-\widehat R(f^*_{\mathcal F})]+[\widehat R(f^*_{\mathcal F})-R(f^*_{\mathcal F})]$.`),b('The first and fourth terms are at most ε by uniform convergence; the second is at most εopt; the third is nonpositive because fhat is an empirical minimizer.','Hạng thứ nhất và thứ tư không quá ε do hội tụ đồng đều; hạng thứ hai không quá εopt; hạng thứ ba không dương vì fhat là minimizer empirical.'),b(String.raw`Summing yields $R(\tilde f)-\min_fR(f)\le2\epsilon+\epsilon_{opt}$. The empirical tolerance does not impose $R(\tilde f)\ge R(\hat f)$.`,String.raw`Cộng lại được $R(\tilde f)-\min_fR(f)\le2\epsilon+\epsilon_{opt}$. Dung sai empirical không buộc $R(\tilde f)\ge R(\hat f)$.`)],
    companions:[
      {prompt:b(String.raw`On a uniform deviation event with ε=0.04 and empirical optimization tolerance εopt=0.01, bound an approximate ERM’s excess over the best member of the class.`,String.raw`Trên biến cố lệch đồng đều với ε=0.04 và dung sai tối ưu empirical εopt=0.01, hãy chặn excess của nghiệm ERM gần đúng so với phần tử tốt nhất trong lớp.`),solution:[b(String.raw`The two uniform-deviation contributions sum to $2\epsilon=0.08$.`,String.raw`Hai đóng góp lệch đồng đều cộng thành $2\epsilon=0.08$.`),b(String.raw`Add the empirical optimization allowance $\epsilon_{opt}=0.01$.`,String.raw`Cộng dung sai tối ưu empirical $\epsilon_{opt}=0.01$.`),b(String.raw`The population excess is at most $0.08+0.01=0.09$.`,String.raw`Excess quần thể không quá $0.08+0.01=0.09$.`)]},
      {prompt:b(String.raw`Let ε=0.02 and εopt=0. If the uniform event holds, find the excess bound and identify the ERM inequality used.`,String.raw`Cho ε=0.02 và εopt=0. Nếu biến cố đồng đều đúng, hãy tìm cận excess và nêu bất đẳng thức ERM được dùng.`),solution:[b('Zero optimization tolerance makes the returned model an empirical minimizer, so its empirical risk is no larger than fhat’s.','Dung sai tối ưu bằng không khiến mô hình trả về là minimizer empirical, nên risk empirical không lớn hơn của fhat.'),b(String.raw`The bound is $2(0.02)+0=0.04$.`,String.raw`Cận là $2(0.02)+0=0.04$.`),b('That sign controls the empirical middle difference in the telescoping proof; it says nothing about the population ordering of the two models.','Dấu đó khống chế hiệu empirical ở giữa trong chứng minh tổng khử; nó không nói thứ tự risk quần thể của hai mô hình.') ]},
      {prompt:b(String.raw`Can an approximate empirical minimizer have lower population risk than the exact empirical ERM while satisfying its empirical tolerance? Explain why the theorem remains valid.`,String.raw`Nghiệm empirical gần đúng có thể có risk quần thể thấp hơn ERM empirical chính xác mà vẫn thỏa dung sai empirical không? Giải thích vì sao định lý vẫn đúng.`),solution:[b('Yes. The stopping rule compares empirical objectives; sampling fluctuation can reverse their population-risk ordering.','Có. Quy tắc dừng so mục tiêu empirical; dao động lấy mẫu có thể đảo thứ tự risk quần thể.'),b(String.raw`Thus $R(\tilde f)-R(\hat f)$ may be negative even when $\widehat R(\tilde f)-\widehat R(\hat f)\ge0$.`,String.raw`Vì vậy $R(\tilde f)-R(\hat f)$ có thể âm dù $\widehat R(\tilde f)-\widehat R(\hat f)\ge0$.`),b('The proof only uses an upper bound εopt on the empirical gap, so a more favorable population gap preserves and can improve the excess-risk inequality.','Chứng minh chỉ dùng cận trên εopt cho khoảng empirical nên khoảng quần thể thuận lợi hơn vẫn giữ và có thể cải thiện bất đẳng thức excess risk.') ]},
    ],
    reviewNote:'Checked finite-class existence, all signs in the telescoping sum, and the use of the empirical—not population—optimization tolerance.',sourceIds:['o-cmu705'],
  },
  'm2-w085-e4': {
    title:b('Search multiplicity widens the uniform radius','Bội số tìm kiếm làm rộng bán kính đồng đều'),
    prompt:b(String.raw`At n=1000 and δ=0.05, compare $\epsilon(M)=\sqrt{\log(2M/\delta)/(2n)}$ for M=20 and $M=2^{20}$. Compute both radii and their ratio, then interpret the larger-class cost.`,String.raw`Với n=1000 và δ=0.05, hãy so $\epsilon(M)=\sqrt{\log(2M/\delta)/(2n)}$ khi M=20 và $M=2^{20}$. Tính hai bán kính và tỷ số rồi diễn giải chi phí lớp lớn hơn.`),
    application:b('A larger search requires simultaneous control over more candidates, so the uniform guarantee pays an increased complexity term.','Tìm kiếm rộng hơn cần khống chế đồng thời nhiều ứng viên, nên cận đồng đều chịu hạng độ phức tạp lớn hơn.'),
    formula:b(String.raw`For fixed n,δ, $\epsilon(M)=\sqrt{\log(2M/\delta)/(2n)}$ and $\epsilon(M_2)/\epsilon(M_1)=\sqrt{\log(2M_2/\delta)/\log(2M_1/\delta)}$.`,String.raw`Với n,δ cố định, $\epsilon(M)=\sqrt{\log(2M/\delta)/(2n)}$ và $\epsilon(M_2)/\epsilon(M_1)=\sqrt{\log(2M_2/\delta)/\log(2M_1/\delta)}$.`),
    steps:[b('Substitute each class size with the same n and δ and natural logarithms.','Thế từng kích thước lớp với cùng n,δ và logarithm tự nhiên.'),b('Compute both radii and divide the larger-class radius by the smaller-class radius.','Tính hai bán kính rồi chia bán kính lớp lớn cho bán kính lớp nhỏ.'),b('Interpret the ratio as a uniform-bound cost, not a claim that the selected model must generalize worse.','Diễn giải tỷ số là chi phí cận đồng đều, không phải khẳng định mô hình được chọn chắc chắn tổng quát hóa kém hơn.')],
    primarySolution:[b(String.raw`For M=20, $2M/\delta=800$ and $\epsilon(20)=\sqrt{\log(800)/2000}\approx0.0578127\approx0.0578$.`,String.raw`Với M=20, $2M/\delta=800$ và $\epsilon(20)=\sqrt{\log(800)/2000}\approx0.0578127\approx0.0578$.`),b(String.raw`For $M=2^{20}$, $2M/\delta=41{,}943{,}040$ and $\epsilon(2^{20})=\sqrt{\log(41{,}943{,}040)/2000}\approx0.0936798\approx0.0937$.`,String.raw`Với $M=2^{20}$, $2M/\delta=41{,}943{,}040$ và $\epsilon(2^{20})=\sqrt{\log(41{,}943{,}040)/2000}\approx0.0936798\approx0.0937$.`),b(String.raw`The ratio is $0.0936798/0.0578127\approx1.6204$.`,String.raw`Tỷ số là $0.0936798/0.0578127\approx1.6204$.`),b('The bound grows to cover every candidate searched; it does not assert the realized winner’s test error must be larger.','Cận tăng để bao phủ mọi ứng viên đã tìm; nó không khẳng định test error của người thắng thực tế phải lớn hơn.')],
    companions:[
      {prompt:b(String.raw`For n=200 and δ=0.1, compare the radii for M=5 and M=500 and find their ratio.`,String.raw`Với n=200 và δ=0.1, hãy so bán kính khi M=5 và M=500 rồi tìm tỷ số.`),solution:[b(String.raw`The log arguments are $100$ and $10{,}000$.`,String.raw`Đối số log lần lượt là $100$ và $10{,}000$.`),b(String.raw`The radii are $\sqrt{\log100/400}=0.1072983$ and $\sqrt{\log10{,}000/400}=0.1517427$.`,String.raw`Hai bán kính là $\sqrt{\log100/400}=0.1072983$ và $\sqrt{\log10{,}000/400}=0.1517427$.`),b(String.raw`Their ratio is $\sqrt{9.210340/4.605170}=\sqrt2\approx1.4142$.`,String.raw`Tỷ số là $\sqrt{9.210340/4.605170}=\sqrt2\approx1.4142$.`)]},
      {prompt:b(String.raw`For n=1000 and δ=0.05, compare the radii at M=10 and M=100.`,String.raw`Với n=1000 và δ=0.05, hãy so bán kính tại M=10 và M=100.`),solution:[b(String.raw`The logarithm arguments are 400 and 4000, giving radii $\sqrt{\log400/2000}$ and $\sqrt{\log4000/2000}$.`,String.raw`Đối số log là 400 và 4000, cho bán kính $\sqrt{\log400/2000}$ và $\sqrt{\log4000/2000}$.`),b(String.raw`Using $\log400=5.991465$ and $\log4000=8.294050$ gives 0.0547333 and 0.0643974.`,String.raw`Dùng $\log400=5.991465$ và $\log4000=8.294050$ được 0.0547333 và 0.0643974.`),b('The 100-model class has the larger radius, but this bound does not determine which fitted model will win on new data.','Lớp 100 mô hình có bán kính lớn hơn, nhưng cận không quyết định mô hình khớp nào thắng trên dữ liệu mới.') ]},
      {prompt:b(String.raw`At fixed n=1000 and δ=0.05, how much does the radius increase when M doubles from 20 to 40?`,String.raw`Với n=1000 và δ=0.05 cố định, bán kính tăng bao nhiêu khi M tăng đôi từ 20 lên 40?`),solution:[b(String.raw`The ratio is $\sqrt{\log(1600)/\log(800)}$.`,String.raw`Tỷ số là $\sqrt{\log(1600)/\log(800)}$.`),b(String.raw`Using logs 7.377759 and 6.684612 gives $\sqrt{1.1037}\approx1.0506$.`,String.raw`Dùng log 7.377759 và 6.684612 được $\sqrt{1.1037}\approx1.0506$.`),b('Class size enters only logarithmically and the result is square-rooted, so doubling M does not double the radius.','Kích thước lớp chỉ đi vào logarithm rồi kết quả lấy căn, nên tăng đôi M không làm bán kính tăng đôi.') ]},
    ],
    reviewNote:'Verified each logarithm and radius using the Node calculator, including the M=20 versus 2^20 ratio; the interpretation concerns the bound rather than realized test performance.',sourceIds:['o-cmu705'],
  },
  'm2-w085-e5': {
    title:b('Overlapping labels break the IID ERM premise','Nhãn chồng lấn phá tiền đề IID của ERM'),
    prompt:b(String.raw`A 20-day return label is attached to each of 1000 adjacent origins. Identify the failed IID step, explain why informal $n_{eff}$ substitution is no proof, and give two defensible alternatives with their estimands or assumptions.`,String.raw`Nhãn lợi suất 20 ngày gắn với 1000 mốc kề nhau. Hãy chỉ ra bước IID thất bại, giải thích vì sao thay $n_{eff}$ tùy ý không phải chứng minh, và nêu hai lựa chọn có thể bảo vệ cùng estimand hoặc giả thiết.`),
    application:b('Adjacent labels reuse daily observations, so an ERM concentration theorem for independent examples cannot be applied by simply changing the sample-size label.','Nhãn kề dùng lại quan sát ngày, nên không thể áp dụng định lý tập trung ERM cho ví dụ độc lập chỉ bằng cách đổi nhãn cỡ mẫu.'),
    formula:b(String.raw`Finite-class Hoeffding assumes IID $Z_i$ and bounded losses: $P(\sup_{f\in\mathcal F}|\widehat R-R|>\epsilon)\le2|\mathcal F|e^{-2n\epsilon^2}$. Overlap violates IID; a dependence-aware uniform theorem needs explicit dependence and rate conditions.`,String.raw`Hoeffding lớp hữu hạn giả sử $Z_i$ IID và loss bị chặn: $P(\sup_{f\in\mathcal F}|\widehat R-R|>\epsilon)\le2|\mathcal F|e^{-2n\epsilon^2}$. Chồng lấn vi phạm IID; định lý đều có xét phụ thuộc cần điều kiện phụ thuộc và tốc độ tường minh.`),
    steps:[b(String.raw`Mark adjacent 20-day windows and count their 19 shared observations.`,String.raw`Đánh dấu cửa sổ 20 ngày kề nhau và đếm 19 quan sát dùng chung.`),b('Identify the product-MGF step in fixed-f Hoeffding; it requires independent summands and fails under overlap.','Xác định bước tích MGF trong Hoeffding f cố định; bước đó cần số hạng độc lập và thất bại khi chồng lấn.'),b('Either change the origin schedule under stated block-independence assumptions or keep all origins and prove dependence-specific uniform concentration.','Hoặc đổi lịch mốc dưới giả thiết block độc lập nêu rõ, hoặc giữ mọi mốc và chứng minh concentration đồng đều có xét phụ thuộc.')],
    primarySolution:[b('Adjacent 20-day windows share 19 daily outcomes, so their losses and empirical-risk summands are dependent.','Hai cửa sổ 20 ngày kề chia sẻ 19 outcome ngày nên loss và hạng risk empirical phụ thuộc.'),b('Fixed-f Hoeffding factors the moment-generating function of the empirical sum using IID observations; a finite-class union bound cannot restore the broken independence premise.','Hoeffding f cố định phân tích moment-generating function của tổng empirical nhờ quan sát IID; cận hợp lớp hữu hạn không khôi phục được tiền đề độc lập đã hỏng.'),b('Nonoverlapping origins can yield independent targets only if the underlying daily blocks are themselves independent; the coarser origin schedule may change the estimand.','Mốc không chồng lấn chỉ cho target độc lập nếu block ngày nền thực sự độc lập; lịch mốc thưa hơn có thể đổi estimand.'),b('Alternatively retain all origins and derive a uniform tail bound under explicit mixing/dependence rates and complexity conditions. A variance-ratio effective size for a mean proves neither exponential tails nor uniform control of the searched class.','Hoặc giữ mọi mốc và suy cận đuôi đồng đều dưới tốc độ mixing/phụ thuộc cùng điều kiện độ phức tạp tường minh. Cỡ hiệu dụng theo tỷ số phương sai của mean không chứng minh đuôi mũ hay khống chế đồng đều lớp được tìm.')],
    companions:[
      {prompt:b(String.raw`A 10-day outcome is attached at every consecutive daily origin. How many days do adjacent labels share, which Hoeffding step fails, and what extra assumption is needed for every tenth origin to be IID?`,String.raw`Outcome 10 ngày gắn tại mọi mốc ngày liên tiếp. Hai nhãn kề chia sẻ bao nhiêu ngày, bước Hoeffding nào thất bại và cần giả thiết gì để mỗi mốc thứ mười là IID?`),solution:[b(String.raw`Adjacent 10-day windows share $10-1=9$ daily observations.`,String.raw`Hai cửa sổ 10 ngày kề chia sẻ $10-1=9$ quan sát ngày.`),b('Their empirical losses are dependent, so the IID product-MGF argument is unavailable.','Loss empirical phụ thuộc nên lập luận tích MGF IID không áp dụng.'),b('Nonoverlap at every tenth origin removes shared target days, but independence still requires the underlying daily blocks or innovations to be independent.','Lấy mỗi mốc thứ mười loại ngày target dùng chung, nhưng độc lập vẫn cần block ngày hoặc innovation nền độc lập.') ]},
      {prompt:b(String.raw`An analyst estimates $n_{eff}=100$ from the mean variance of 500 overlapping five-day losses and substitutes 100 into an IID finite-class tail bound. What is missing and one valid alternative?`,String.raw`Nhà phân tích ước lượng $n_{eff}=100$ từ phương sai mean của 500 loss năm ngày chồng lấn rồi thế 100 vào cận đuôi lớp hữu hạn IID. Thiếu gì và có lựa chọn hợp lệ nào?`),solution:[b('A variance-ratio effective size describes the uncertainty of a specified mean under a model; it does not establish an exponential tail.','Cỡ hiệu dụng theo tỷ số phương sai mô tả bất định của mean cụ thể dưới mô hình; nó không thiết lập đuôi mũ.'),b('Overlapping losses remain dependent, so the IID product-MGF premise is false.','Loss chồng lấn vẫn phụ thuộc nên tiền đề tích MGF IID sai.'),b('Use a justified nonoverlap design with block independence and state its changed estimand, or prove a uniform bound under explicit dependence assumptions.','Dùng thiết kế không chồng lấn có block độc lập được biện minh và nêu estimand đổi, hoặc chứng minh cận đồng đều dưới giả thiết phụ thuộc tường minh.') ]},
      {prompt:b(String.raw`Eight bounded-loss forecasters are evaluated on overlapping origins from a strongly mixing process. Can the IID finite-class theorem be cited? What must a replacement bound specify?`,String.raw`Tám forecaster loss bị chặn được đánh giá tại mốc chồng lấn từ quá trình mixing mạnh. Có thể viện dẫn định lý lớp hữu hạn IID không? Cận thay thế cần nêu gì?`),solution:[b('No. Strong mixing still permits dependence, so bounded loss alone does not justify IID Hoeffding.','Không. Mixing mạnh vẫn cho phép phụ thuộc nên loss bị chặn riêng không biện minh Hoeffding IID.'),b('A replacement must state mixing coefficients and rates, moment or boundedness assumptions, and the relevant sample/block dependence scale.','Cận thay thế phải nêu hệ số và tốc độ mixing, giả thiết moment hoặc bị chặn, cùng thang phụ thuộc mẫu/block phù hợp.'),b('It must yield a valid uniform tail rate over all eight candidates with its complexity term; an informal n_eff is not that theorem.','Nó phải cho tốc độ đuôi đồng đều hợp lệ trên cả tám ứng viên cùng hạng độ phức tạp; n_eff tùy ý không phải định lý đó.') ]},
    ],
    reviewNote:'Checked the 19-day overlap count and the exact IID product-MGF requirement; alternatives explicitly alter the origin estimand or require a dependence-aware uniform tail theorem.',sourceIds:['o-cmu705','o-cmu-mixing'],
  },
  'daily-spectral-coherence': {
    title:b('Cross-spectrum and spectral coherence','Phổ chéo và coherence phổ'),
    prompt:b(String.raw`At a fixed frequency, let $f_{xx}=4$, $f_{yy}=9$, and $f_{xy}=3+3i$. Compute coherence and test whether the spectral matrix is PSD. Then repeat the validity check with $f_{xy}=7$.`,String.raw`Tại một tần số cố định, cho $f_{xx}=4$, $f_{yy}=9$, $f_{xy}=3+3i$. Tính coherence và kiểm tra ma trận phổ PSD. Sau đó kiểm tra tính hợp lệ lại với $f_{xy}=7$.`),
    application:b('Coherence measures normalized cross-series association at a frequency; a value above one signals a spectral matrix that cannot be positive semidefinite.','Coherence đo liên hệ chuẩn hóa giữa hai chuỗi tại một tần số; giá trị lớn hơn một báo ma trận phổ không thể nửa xác định dương.'),
    formula:b(String.raw`For $F(\omega)=\begin{bmatrix}f_{xx}&f_{xy}\\\overline{f_{xy}}&f_{yy}\end{bmatrix}\succeq0$, $|f_{xy}|^2\le f_{xx}f_{yy}$; if both diagonal terms are positive, $C=|f_{xy}|^2/(f_{xx}f_{yy})\in[0,1]$.`,String.raw`Với $F(\omega)=\begin{bmatrix}f_{xx}&f_{xy}\\\overline{f_{xy}}&f_{yy}\end{bmatrix}\succeq0$, $|f_{xy}|^2\le f_{xx}f_{yy}$; nếu cả hai phần tử đường chéo dương thì $C=|f_{xy}|^2/(f_{xx}f_{yy})\in[0,1]$.`),
    steps:[b('For a 2×2 Hermitian matrix, require nonnegative diagonal entries and determinant.','Với ma trận Hermitian 2×2, yêu cầu phần tử đường chéo và định thức không âm.'),b(String.raw`Compute the determinant $f_{xx}f_{yy}-|f_{xy}|^2$ using the complex modulus, not the real part alone.`,String.raw`Tính định thức $f_{xx}f_{yy}-|f_{xy}|^2$ bằng modulus phức, không chỉ phần thực.`),b('Divide by the positive diagonal product to obtain coherence; if a diagonal is zero, PSD forces the cross term to vanish and the ratio is undefined.','Chia cho tích đường chéo dương để được coherence; nếu một đường chéo bằng không thì PSD buộc hạng chéo bằng không và tỷ số không xác định.')],
    primarySolution:[b(String.raw`The cross-spectrum modulus squared is $|3+3i|^2=3^2+3^2=18$.`,String.raw`Modulus bình phương của phổ chéo là $|3+3i|^2=3^2+3^2=18$.`),b(String.raw`The diagonal product is $f_{xx}f_{yy}=4(9)=36$, so $C=18/36=1/2$.`,String.raw`Tích đường chéo là $f_{xx}f_{yy}=4(9)=36$, nên $C=18/36=1/2$.`),b(String.raw`The Hermitian matrix has positive diagonal entries and determinant $36-18=18>0$, so it is positive definite and hence PSD.`,String.raw`Ma trận Hermitian có đường chéo dương và định thức $36-18=18>0$, nên xác định dương và do đó PSD.`),b(String.raw`If $f_{xy}=7$, then $|f_{xy}|^2=49$, determinant $36-49=-13$, and formal coherence $49/36>1$; this violates PSD and is not a valid spectral matrix.`,String.raw`Nếu $f_{xy}=7$ thì $|f_{xy}|^2=49$, định thức $36-49=-13$, coherence hình thức $49/36>1$; điều này vi phạm PSD nên không phải ma trận phổ hợp lệ.`)],
    companions:[
      {prompt:b(String.raw`At a frequency, $f_{xx}=2$, $f_{yy}=8$, and $f_{xy}=2i$. Compute coherence and determinant, then classify the matrix.`,String.raw`Tại một tần số, $f_{xx}=2$, $f_{yy}=8$, $f_{xy}=2i$. Tính coherence và định thức rồi phân loại ma trận.`),solution:[b(String.raw`The cross modulus squared is $|2i|^2=4$, while the diagonal product is $2(8)=16$.`,String.raw`Modulus bình phương của hạng chéo là $|2i|^2=4$, còn tích đường chéo là $2(8)=16$.`),b(String.raw`Coherence is $C=4/16=0.25$.`,String.raw`Coherence là $C=4/16=0.25$.`),b(String.raw`The determinant is $16-4=12>0$ and both diagonal terms are positive, so the matrix is positive definite.`,String.raw`Định thức là $16-4=12>0$ và cả hai đường chéo dương nên ma trận xác định dương.`)]},
      {prompt:b(String.raw`Let $f_{xx}=1$, $f_{yy}=9$, and $f_{xy}=3$. Compute coherence and explain the determinant-zero boundary.`,String.raw`Cho $f_{xx}=1$, $f_{yy}=9$, $f_{xy}=3$. Tính coherence và giải thích biên định thức bằng không.`),solution:[b(String.raw`The squared cross modulus is $|3|^2=9$, equal to the diagonal product $1(9)=9$.`,String.raw`Modulus chéo bình phương là $|3|^2=9$, bằng tích đường chéo $1(9)=9$.`),b(String.raw`Thus $C=9/9=1$ and the determinant is zero.`,String.raw`Vậy $C=9/9=1$ và định thức bằng không.`),b('The Hermitian matrix is PSD but singular (rank one); coherence one is an admissible boundary value, not an automatic proof of causality.','Ma trận Hermitian PSD nhưng suy biến (hạng một); coherence bằng một là giá trị biên hợp lệ, không tự động chứng minh quan hệ nhân quả.') ]},
      {prompt:b(String.raw`Suppose $f_{xx}=0$ and $f_{yy}=5$. What must PSD imply about $f_{xy}$, and why is the coherence ratio undefined?`,String.raw`Giả sử $f_{xx}=0$ và $f_{yy}=5$. PSD buộc $f_{xy}$ thế nào và vì sao tỷ số coherence không xác định?`),solution:[b(String.raw`The determinant condition is $0\cdot5-|f_{xy}|^2\ge0$.`,String.raw`Điều kiện định thức là $0\cdot5-|f_{xy}|^2\ge0$.`),b(String.raw`Since a squared modulus is nonnegative, this forces $|f_{xy}|^2=0$, hence $f_{xy}=0$.`,String.raw`Vì modulus bình phương không âm, điều này buộc $|f_{xy}|^2=0$, nên $f_{xy}=0$.`),b(String.raw`The denominator $f_{xx}f_{yy}$ is zero, so normalized coherence is undefined; one should not divide by zero or report a numeric value.`,String.raw`Mẫu số $f_{xx}f_{yy}$ bằng không nên coherence chuẩn hóa không xác định; không được chia cho không hay báo giá trị số.`)]},
    ],
    reviewNote:'Checked the complex modulus, determinant signs, valid PSD boundary at coherence one, and zero-diagonal case where coherence is undefined; the 7-valued cross-spectrum is explicitly invalid.',sourceIds:['o-mit-ts'],
  },
};

export default lessons;
